package continuity

import (
	"chain/runtime/unsafe"
	"strconv"
)

const maintainer = address("g18r7ee0utsm07jd6f7qnxc9us7yz2qpk8rednrs")

var revision int
var active bool

func Publish(_ realm) {
	if unsafe.OriginCaller() != maintainer {
		panic("maintainer signature required")
	}
	if active {
		panic("notice is already active")
	}
	revision++
	active = true
}

func Withdraw(_ realm, expectedRevision int) {
	if unsafe.OriginCaller() != maintainer {
		panic("maintainer signature required")
	}
	if !active || expectedRevision != revision {
		panic("notice is inactive or revision has changed")
	}
	active = false
}

func Render(_ string) string {
	if !active {
		return "# Release notice\n\nStatus: withdrawn or unpublished.\n\nRevision: " + strconv.Itoa(revision) + "."
	}
	return "# Release notice\n\nStatus: active.\n\nRevision: " + strconv.Itoa(revision) +
		".\n\n[Withdraw release notice](/r/g18r7ee0utsm07jd6f7qnxc9us7yz2qpk8rednrs/continuity$help&func=Withdraw&expectedRevision=" + strconv.Itoa(revision) + ")"
}

// Package escrowmath provides pure, deterministic arithmetic, quorum tallying,
// split conservation, formatting, and JSON encoding utilities for MilestoneVault
// and any third-party Gno.land escrow or bounty realms.
package escrowmath

import (
	"errors"
	"strconv"
	"strings"
)

const (
	MaxMilestones  = 12
	MaxArbiters    = 5
	BpsDenominator = int64(10000)
	UgnotPerGnot   = int64(1000000)
	MaxSafeAmount  = int64(900000000000000) // 900M GNOT guard against int64 bps overflow
)

var (
	ErrNoMilestones       = errors.New("at least one milestone is required")
	ErrTooManyMilestones  = errors.New("exceeds maximum milestone count (12)")
	ErrInvalidAmount      = errors.New("milestone amount must be positive and within safe bounds")
	ErrDepositMismatch    = errors.New("sum of milestone amounts must equal exact deposit sent")
	ErrInvalidArbiterList = errors.New("arbiter count must be between 1 and 5")
)

// ValidateMilestones verifies every milestone amount is positive, overflow-safe,
// sums strictly to totalDeposit, and returns proportional basis points (0..10000).
func ValidateMilestones(amounts []int64, totalDeposit int64) ([]int64, error) {
	if len(amounts) == 0 {
		return nil, ErrNoMilestones
	}
	if len(amounts) > MaxMilestones {
		return nil, ErrTooManyMilestones
	}
	if totalDeposit <= 0 || totalDeposit > MaxSafeAmount {
		return nil, ErrInvalidAmount
	}

	var sum int64
	for _, a := range amounts {
		if a <= 0 || a > MaxSafeAmount {
			return nil, ErrInvalidAmount
		}
		if sum > MaxSafeAmount-a {
			return nil, ErrInvalidAmount
		}
		sum += a
	}
	if sum != totalDeposit {
		return nil, ErrDepositMismatch
	}

	bps := make([]int64, len(amounts))
	var bpsSum int64
	for i, a := range amounts {
		share := (a * BpsDenominator) / totalDeposit
		bps[i] = share
		bpsSum += share
	}
	// Assign any integer rounding remainder to the final milestone so bps sums to 10000.
	if bpsSum < BpsDenominator {
		bps[len(bps)-1] += BpsDenominator - bpsSum
	}
	return bps, nil
}

// QuorumThreshold returns the strict majority needed for an arbiter council of size n.
func QuorumThreshold(arbiterCount int) int {
	if arbiterCount <= 0 {
		return 1
	}
	return (arbiterCount / 2) + 1
}

// EvaluateDisputeTally checks whether any dispute verdict has reached strict majority.
// If all arbiters have cast votes and no single verdict reached majority (deadlock),
// it deterministically resolves to "SPLIT" so escrowed funds can never be trapped.
func EvaluateDisputeTally(releaseVotes, refundVotes, splitVotes, arbiterCount int) (string, bool) {
	q := QuorumThreshold(arbiterCount)
	if releaseVotes >= q {
		return "RELEASE", true
	}
	if refundVotes >= q {
		return "REFUND", true
	}
	if splitVotes >= q {
		return "SPLIT", true
	}
	totalVotes := releaseVotes + refundVotes + splitVotes
	if arbiterCount > 0 && totalVotes >= arbiterCount {
		return "SPLIT", true
	}
	return "", false
}

// ComputeSplit divides an escrowed milestone 50/50 between builder and sponsor
// while strictly conserving every ugnot (builder receives the 1 ugnot remainder if odd).
func ComputeSplit(amount int64) (builderShare int64, sponsorShare int64) {
	if amount <= 0 {
		return 0, 0
	}
	sponsorShare = amount / 2
	builderShare = amount - sponsorShare
	return builderShare, sponsorShare
}

// FormatUGNOT formats an integer ugnot balance into a clean GNOT display string.
func FormatUGNOT(amount int64) string {
	neg := false
	if amount < 0 {
		neg = true
		amount = -amount
	}
	whole := amount / UgnotPerGnot
	frac := amount % UgnotPerGnot

	prefix := ""
	if neg {
		prefix = "-"
	}
	if frac == 0 {
		return prefix + strconv.FormatInt(whole, 10) + " GNOT"
	}

	fracStr := strconv.FormatInt(frac, 10)
	for len(fracStr) < 6 {
		fracStr = "0" + fracStr
	}
	fracStr = strings.TrimRight(fracStr, "0")
	return prefix + strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

// RenderProgressBar produces a deterministic Unicode bar for gnoweb Markdown views.
func RenderProgressBar(completed, total int64, width int) string {
	if width <= 0 {
		width = 16
	}
	pct := int64(0)
	if total > 0 {
		if completed > total {
			completed = total
		}
		if completed < 0 {
			completed = 0
		}
		pct = (completed * 100) / total
	}
	filled := int((pct * int64(width)) / 100)
	if filled > width {
		filled = width
	}
	var sb strings.Builder
	sb.WriteString("[")
	for i := 0; i < width; i++ {
		if i < filled {
			sb.WriteString("█")
		} else {
			sb.WriteString("░")
		}
	}
	sb.WriteString("] ")
	sb.WriteString(strconv.FormatInt(pct, 10))
	sb.WriteString("%")
	return sb.String()
}

// SplitPipe splits a pipe-delimited string and trims whitespace from non-empty items.
func SplitPipe(input string) []string {
	if strings.TrimSpace(input) == "" {
		return nil
	}
	raw := strings.Split(input, "|")
	out := make([]string, 0, len(raw))
	for _, s := range raw {
		t := strings.TrimSpace(s)
		if t != "" {
			out = append(out, t)
		}
	}
	return out
}

// SplitCSV splits a comma-delimited string and trims whitespace from non-empty items.
func SplitCSV(input string) []string {
	if strings.TrimSpace(input) == "" {
		return nil
	}
	raw := strings.Split(input, ",")
	out := make([]string, 0, len(raw))
	for _, s := range raw {
		t := strings.TrimSpace(s)
		if t != "" {
			out = append(out, t)
		}
	}
	return out
}

// ParseAmountsCSV parses comma-separated positive ugnot integers.
func ParseAmountsCSV(input string) ([]int64, error) {
	parts := SplitCSV(input)
	if len(parts) == 0 {
		return nil, ErrNoMilestones
	}
	out := make([]int64, len(parts))
	for i, p := range parts {
		v, err := strconv.ParseInt(p, 10, 64)
		if err != nil || v <= 0 {
			return nil, ErrInvalidAmount
		}
		out[i] = v
	}
	return out, nil
}

// EscapeJSON escapes control characters and quotes for deterministic JSON rendering.
func EscapeJSON(s string) string {
	var sb strings.Builder
	sb.Grow(len(s) + 8)
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if c < 0x20 {
				sb.WriteString(" ")
			} else {
				sb.WriteByte(c)
			}
		}
	}
	return sb.String()
}

package escrowmath

import "testing"

func TestValidateMilestones(t *testing.T) {
	bps, err := ValidateMilestones([]int64{1000000, 2000000, 1000000}, 4000000)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(bps) != 3 || bps[0] != 2500 || bps[1] != 5000 || bps[2] != 2500 {
		t.Fatalf("unexpected bps: %v", bps)
	}

	// Rounding remainder goes to last milestone so total equals 10000 bps.
	bpsOdd, err := ValidateMilestones([]int64{100, 100, 100}, 300)
	if err != nil {
		t.Fatalf("unexpected error on equal 3-way split: %v", err)
	}
	if bpsOdd[0]+bpsOdd[1]+bpsOdd[2] != BpsDenominator {
		t.Fatalf("expected bps sum 10000, got %d", bpsOdd[0]+bpsOdd[1]+bpsOdd[2])
	}

	// Sum mismatch must fail.
	if _, err := ValidateMilestones([]int64{500, 500}, 999); err != ErrDepositMismatch {
		t.Fatalf("expected ErrDepositMismatch, got %v", err)
	}

	// Zero or negative amounts must fail.
	if _, err := ValidateMilestones([]int64{0, 1000}, 1000); err != ErrInvalidAmount {
		t.Fatalf("expected ErrInvalidAmount, got %v", err)
	}

	// Empty milestones must fail.
	if _, err := ValidateMilestones(nil, 1000); err != ErrNoMilestones {
		t.Fatalf("expected ErrNoMilestones, got %v", err)
	}
}

func TestDisputeQuorumAndDeadlock(t *testing.T) {
	if QuorumThreshold(1) != 1 || QuorumThreshold(3) != 2 || QuorumThreshold(5) != 3 {
		t.Fatalf("wrong quorum threshold calculation")
	}

	if out, ok := EvaluateDisputeTally(1, 0, 0, 3); ok || out != "" {
		t.Fatalf("1 of 3 should not reach quorum, got %s %v", out, ok)
	}
	if out, ok := EvaluateDisputeTally(2, 1, 0, 3); !ok || out != "RELEASE" {
		t.Fatalf("expected RELEASE, got %s %v", out, ok)
	}
	if out, ok := EvaluateDisputeTally(0, 2, 0, 3); !ok || out != "REFUND" {
		t.Fatalf("expected REFUND, got %s %v", out, ok)
	}
	// 3-way deadlock (1-1-1 out of 3 arbiters) must deterministically resolve to SPLIT.
	if out, ok := EvaluateDisputeTally(1, 1, 1, 3); !ok || out != "SPLIT" {
		t.Fatalf("expected deadlock SPLIT fallback, got %s %v", out, ok)
	}
}

func TestComputeSplitConservation(t *testing.T) {
	b, s := ComputeSplit(1001)
	if b != 501 || s != 500 || b+s != 1001 {
		t.Fatalf("odd split not conserved: %d + %d", b, s)
	}
	b2, s2 := ComputeSplit(2000000)
	if b2 != 1000000 || s2 != 1000000 {
		t.Fatalf("even split wrong: %d / %d", b2, s2)
	}
}

func TestFormatAndProgress(t *testing.T) {
	if got := FormatUGNOT(1500000); got != "1.5 GNOT" {
		t.Fatalf("got %q, want 1.5 GNOT", got)
	}
	if got := FormatUGNOT(2000000); got != "2 GNOT" {
		t.Fatalf("got %q, want 2 GNOT", got)
	}
	if got := FormatUGNOT(500); got != "0.0005 GNOT" {
		t.Fatalf("got %q, want 0.0005 GNOT", got)
	}
	bar := RenderProgressBar(50, 100, 10)
	if bar != "[█████░░░░░] 50%" {
		t.Fatalf("unexpected progress bar: %q", bar)
	}
	if esc := EscapeJSON("hi \"gno\"\nline2"); esc != `hi \"gno\"\nline2` {
		t.Fatalf("unexpected escaped json: %q", esc)
	}
}

// Package roscasched derives the payout order of a rotating savings circle.
//
// The order is a Fisher-Yates shuffle over SHA-256(circle id | activation
// height | sorted member addresses): deterministic on every node, and not
// choosable by the circle's creator.
package roscasched

import (
	"crypto/sha256"
	"strconv"
	"strings"
)

// Seed builds the activation seed for a circle. Mixing the circle ID, the
// activation height and the sorted member set means the payout order cannot
// be chosen by the creator after the fact, and every node derives the same
// order from the same chain state.
func Seed(circleID uint64, height int64, members []string) string {
	parts := make([]string, len(members))
	copy(parts, members)
	sortStrings(parts)
	return strconv.FormatUint(circleID, 10) + "|" +
		strconv.FormatInt(height, 10) + "|" +
		strings.Join(parts, ",")
}

// Order returns a deterministic permutation of 0..n-1 derived from seed.
//
// It is a Fisher-Yates shuffle over bytes of SHA-256(seed:counter), so the
// same seed always yields the same order on every machine and every replay.
func Order(n int, seed string) []int {
	idx := make([]int, n)
	for i := 0; i < n; i++ {
		idx[i] = i
	}
	if n < 2 {
		return idx
	}
	p := newPRNG(seed)
	for i := n - 1; i > 0; i-- {
		j := int(p.next() % uint64(i+1))
		idx[i], idx[j] = idx[j], idx[i]
	}
	return idx
}


// --- internals ---

// prng is a deterministic byte stream: SHA-256(seed:counter) concatenated.
type prng struct {
	seed string
	buf  []byte
	ctr  int
}

func newPRNG(seed string) *prng { return &prng{seed: seed} }

func (p *prng) next() uint64 {
	for len(p.buf) < 8 {
		h := sha256.Sum256([]byte(p.seed + ":" + strconv.Itoa(p.ctr)))
		p.ctr++
		p.buf = append(p.buf, h[:]...)
	}
	b := p.buf[:8]
	p.buf = p.buf[8:]
	var v uint64
	for i := 0; i < 8; i++ {
		v = v<<8 | uint64(b[i])
	}
	return v
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// Package rosca holds the economics of a rotating savings circle (ROSCA):
// parameters and validation, pot maths, exact penalty splitting, formatting.
//
// Deliberately small: on a chain that verifies packages off-chain before
// enabling them, a package under the verifier's budget goes live in seconds.
// The deterministic schedule lives in the sibling package roscasched.
// Package rosca is a dependency-free toolkit for building rotating savings
// and credit associations (ROSCA - "arisan", "tanda", "chit fund", "susus")
// on Gno.land.
//
// It contains no state and no realm capability of its own: the economics,
// the deterministic payout schedule and the presentation helpers are pure
// functions, so any realm can import this package and add a savings circle
// to its own state machine without re-deriving the hard parts.
//
// The companion realm gno.land/r/<addr>/kolektif is the reference
// implementation; it imports exactly these helpers.
package rosca

import (
	"errors"
	"strconv"
	"strings"
)

// Status is the lifecycle stage of a circle.
type Status uint8

const (
	// StatusOpen collects members and collateral. Nothing is paid out.
	StatusOpen Status = iota
	// StatusActive is a full circle that is paying round by round.
	StatusActive
	// StatusComplete means every payout happened and collateral was returned.
	StatusComplete
)

// String renders a status as a short label.
func (s Status) String() string {
	switch s {
	case StatusOpen:
		return "OPEN"
	case StatusActive:
		return "ACTIVE"
	case StatusComplete:
		return "COMPLETE"
	}
	return "UNKNOWN"
}

// Limits keep a circle inside numbers the reference realm can render and
// settle safely. They are advisory: an importing realm may enforce others.
const (
	MinSize          = 3
	MaxSize          = 50
	MinContribution  = int64(1000)         // 0.001 GNOT
	MaxContribution  = int64(100000000000) // 100,000 GNOT
	MinRoundSpan     = int64(60)           // 1 minute
	MaxRoundSpan     = int64(2592000)      // 30 days
	MaxNameLen       = 64
	DefaultRoundSpan = int64(604800) // 7 days
	UgnotPerGnot     = int64(1000000)
)

// Params is the immutable economics of a circle.
//
// Contribution is what each member pays every round. Collateral is what a
// member locks when joining; it is returned at completion and slashed into
// the penalty fund when the member defaults.
type Params struct {
	Contribution int64
	Collateral   int64
	Size         int
	RoundSpan    int64 // seconds per round
}

// Validate checks the parameters of a circle.
func (p Params) Validate() error {
	if p.Size < MinSize || p.Size > MaxSize {
		return errors.New("size must be between 3 and 50 members")
	}
	if p.Contribution < MinContribution || p.Contribution > MaxContribution {
		return errors.New("contribution out of range")
	}
	if p.Collateral != p.Contribution {
		return errors.New("collateral must equal one round contribution")
	}
	if p.RoundSpan < MinRoundSpan || p.RoundSpan > MaxRoundSpan {
		return errors.New("round span must be between 1 minute and 30 days")
	}
	return nil
}

// Pot is the payout one round produces when every seat pays.
func (p Params) Pot() int64 {
	return p.Contribution * int64(p.Size)
}

// Locked is the capital a circle needs at rest: every seat's collateral.
func (p Params) Locked() int64 {
	return p.Collateral * int64(p.Size)
}

// NetPerMember is the net cash flow of an ideal circle (no defaults) for a
// member who stays to the end: they pay Size contributions and receive one
// pot of Size contributions. It is always zero, which is the point of a
// ROSCA: it is a savings rotation, not a loan.
func (p Params) NetPerMember() int64 {
	return p.Pot() - p.Contribution*int64(p.Size)
}

// Split divides amount into n shares. Any remainder goes one unit at a time
// to the first shares, so the shares always add up to amount exactly.
func Split(amount int64, n int) []int64 {
	out := make([]int64, n)
	if n <= 0 || amount <= 0 {
		return out
	}
	base := amount / int64(n)
	rem := amount % int64(n)
	for i := 0; i < n; i++ {
		out[i] = base
	}
	for i := 0; int64(i) < rem; i++ {
		out[i]++
	}
	return out
}

// Gnot formats a ugnot amount as GNOT with up to six decimals and no
// trailing zeros: 1500000 -> "1.5", 1000 -> "0.001".
func Gnot(ugnot int64) string {
	neg := ugnot < 0
	if neg {
		ugnot = -ugnot
	}
	whole := ugnot / UgnotPerGnot
	frac := ugnot % UgnotPerGnot
	s := strconv.FormatInt(whole, 10)
	if frac > 0 {
		f := strconv.FormatInt(frac+UgnotPerGnot, 10)[1:] // zero padded, 6 digits
		f = strings.TrimRight(f, "0")
		s += "." + f
	}
	if neg {
		s = "-" + s
	}
	return s
}

// HumanDuration renders a number of seconds as a compact human string:
// 90061 -> "1d 1h", 3600 -> "1h", 45 -> "45s".
func HumanDuration(seconds int64) string {
	if seconds <= 0 {
		return "now"
	}
	d := seconds / 86400
	h := (seconds % 86400) / 3600
	m := (seconds % 3600) / 60
	s := seconds % 60
	out := ""
	if d > 0 {
		out += strconv.FormatInt(d, 10) + "d "
	}
	if h > 0 && d < 100 {
		out += strconv.FormatInt(h, 10) + "h "
	}
	if m > 0 && d == 0 {
		out += strconv.FormatInt(m, 10) + "m "
	}
	if s > 0 && d == 0 && h == 0 {
		out += strconv.FormatInt(s, 10) + "s"
	}
	return strings.TrimSpace(out)
}

// Bar renders a fixed width progress bar in plain ASCII, so it survives every
// monospace font gnoweb may be served with: "[###---]".
func Bar(done, total, width int) string {
	if width <= 0 {
		return ""
	}
	if total <= 0 || done <= 0 {
		return "[" + strings.Repeat("-", width) + "]"
	}
	if done > total {
		done = total
	}
	filled := done * width / total
	if filled == 0 {
		filled = 1
	}
	if filled > width {
		filled = width
	}
	return "[" + strings.Repeat("#", filled) + strings.Repeat("-", width-filled) + "]"
}

// ShortAddr shortens a bech32 address for tables: g1abc...wxyz.
func ShortAddr(addr string) string {
	if len(addr) <= 14 {
		return addr
	}
	return addr[:7] + "..." + addr[len(addr)-4:]
}

// Package milestonevault implements a trustless on-chain milestone escrow,
// bounty assignment, deadman-timeout release, and arbiter-quorum dispute protocol.
//
// Security architecture (Gno v1.8.0):
//   - Sub-realm escrow isolation: every vault mints a dedicated cur.Sub("v<id>")
//     escrow address so Vault A's funds are structurally isolated from Vault B
//     at the bank-keeper level.
//   - Ephemeral bankers only: no banker.Banker value is ever persisted in state.
//   - Checks-Effects-Interactions: all state transitions commit before SendCoins.
package milestonevault

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1p8ssx7g7fz268k6jc0krpu9enuen4hjvf4599j/escrowmath"
)

var (
	realmPkgPath        string
	vaults              []*Vault
	builderOrder        []address
	builderStatsByAddr  = make(map[address]*BuilderStats)
	totalDepositedUgnot int64
	totalReleasedUgnot  int64
	totalRefundedUgnot  int64
)

func getOrCreateBuilderStats(addr address) *BuilderStats {
	st, ok := builderStatsByAddr[addr]
	if !ok {
		st = &BuilderStats{Address: addr}
		builderStatsByAddr[addr] = st
		builderOrder = append(builderOrder, addr)
	}
	return st
}

func parseArbiters(csv string, sponsor address) []address {
	parts := escrowmath.SplitCSV(csv)
	if len(parts) == 0 || len(parts) > escrowmath.MaxArbiters {
		panic("arbiters count must be between 1 and 5")
	}
	seen := make(map[address]bool, len(parts))
	out := make([]address, 0, len(parts))
	for _, p := range parts {
		addr := address(p)
		if !addr.IsValid() {
			panic("invalid arbiter address: " + p)
		}
		if seen[addr] {
			panic("duplicate arbiter address: " + p)
		}
		seen[addr] = true
		out = append(out, addr)
	}
	_ = sponsor
	return out
}

func parsePositiveInt64(s string, field string) int64 {
	v, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil || v <= 0 {
		panic("invalid positive integer for " + field)
	}
	return v
}

func parsePositiveInt(s string, field string) int {
	v, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil || v <= 0 {
		panic("invalid positive integer for " + field)
	}
	return v
}

// CreateVault creates a new milestone escrow vault and atomically moves the exact
// ugnot sent in the transaction into an isolated sub-realm escrow address cur.Sub("v<id>").
//
// Parameters:
//   - title: short project title
//   - description: scope summary
//   - milestoneTitlesPipe: pipe-separated milestone names (e.g. "Spec|Build|Audit")
//   - milestoneAmountsCSV: comma-separated ugnot amounts summing to sent ugnot
//   - arbitersCSV: comma-separated 1..5 arbiter addresses
//   - timeoutBlocksStr: positive block count after submission when builder may claim timeout release
func CreateVault(
	cur realm,
	title string,
	description string,
	milestoneTitlesPipe string,
	milestoneAmountsCSV string,
	arbitersCSV string,
	timeoutBlocksStr string,
) int {
	if !cur.Previous().IsUserCall() {
		panic("CreateVault requires a direct user call (maketx call)")
	}
	realmPkgPath = cur.PkgPath()

	title = strings.TrimSpace(title)
	description = strings.TrimSpace(description)
	if title == "" {
		panic("vault title cannot be empty")
	}

	titles := escrowmath.SplitPipe(milestoneTitlesPipe)
	amounts, err := escrowmath.ParseAmountsCSV(milestoneAmountsCSV)
	if err != nil {
		panic(err.Error())
	}
	if len(titles) != len(amounts) {
		panic("milestone titles count must match milestone amounts count")
	}

	sent := unsafe.OriginSend()
	deposit := sent.AmountOf(DenomUGNOT)
	bps, err := escrowmath.ValidateMilestones(amounts, deposit)
	if err != nil {
		panic(err.Error())
	}

	sponsor := cur.Previous().Address()
	arbiters := parseArbiters(arbitersCSV, sponsor)
	timeoutBlocks := parsePositiveInt64(timeoutBlocksStr, "timeoutBlocks")

	id := len(vaults) + 1
	subPath := vaultSubPath(id)
	sub := cur.Sub(subPath)
	escrowAddr := sub.Address()

	ms := make([]*Milestone, len(amounts))
	for i := range amounts {
		ms[i] = &Milestone{
			ID:          i + 1,
			Title:       titles[i],
			AmountUgnot: amounts[i],
			Bps:         bps[i],
			Status:      MilestonePending,
		}
	}

	v := &Vault{
		ID:                id,
		Title:             title,
		Description:       description,
		Sponsor:           sponsor,
		SubPath:           subPath,
		EscrowAddr:        escrowAddr,
		Status:            VaultStatusOpen,
		TotalDepositUgnot: deposit,
		TimeoutBlocks:     timeoutBlocks,
		CreatedAtHeight:   runtime.ChainHeight(),
		Arbiters:          arbiters,
		Milestones:        ms,
		Dispute:           &Dispute{QuorumRequired: escrowmath.QuorumThreshold(len(arbiters))},
	}

	// Effects before external bank transfer.
	vaults = append(vaults, v)
	totalDepositedUgnot += deposit

	// Isolate the vault's ugnot inside its dedicated sub-realm account.
	hostBanker := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	hostBanker.SendCoins(cur.Address(), escrowAddr, chain.NewCoins(chain.NewCoin(DenomUGNOT, deposit)))

	chain.Emit(
		"VaultCreated",
		"vault_id", strconv.Itoa(id),
		"sponsor", string(sponsor),
		"escrow_addr", string(escrowAddr),
		"deposit_ugnot", strconv.FormatInt(deposit, 10),
		"milestones", strconv.Itoa(len(ms)),
	)
	return id
}

// ApplyForVault lets any builder submit an on-chain proposal for an OPEN vault.
func ApplyForVault(cur realm, vaultIDStr string, pitch string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusOpen {
		panic("vault is not open for applications")
	}
	caller := cur.Previous().Address()
	if caller == v.Sponsor {
		panic("sponsor cannot apply to own vault")
	}
	pitch = strings.TrimSpace(pitch)
	if pitch == "" {
		panic("application pitch cannot be empty")
	}
	for _, app := range v.Applications {
		if app.Builder == caller {
			panic("builder already applied to this vault")
		}
	}
	v.Applications = append(v.Applications, &Application{
		Builder:         caller,
		Pitch:           pitch,
		AppliedAtHeight: runtime.ChainHeight(),
	})
	chain.Emit(
		"VaultApplied",
		"vault_id", strconv.Itoa(v.ID),
		"builder", string(caller),
	)
}

// AssignBuilder allows the sponsor to assign a builder to an OPEN vault, transitioning it to ACTIVE.
func AssignBuilder(cur realm, vaultIDStr string, builderAddrStr string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusOpen {
		panic("vault must be OPEN to assign a builder")
	}
	caller := cur.Previous().Address()
	if caller != v.Sponsor {
		panic("only the vault sponsor can assign a builder")
	}
	builder := address(strings.TrimSpace(builderAddrStr))
	if !builder.IsValid() {
		panic("invalid builder address")
	}
	if builder == v.Sponsor {
		panic("sponsor cannot assign themselves as builder")
	}
	v.Builder = builder
	v.Status = VaultStatusActive
	getOrCreateBuilderStats(builder)

	chain.Emit(
		"BuilderAssigned",
		"vault_id", strconv.Itoa(v.ID),
		"builder", string(builder),
	)
}

// SubmitMilestone lets the assigned builder attach verifiable proof (commit/PR/URL) for a PENDING milestone.
func SubmitMilestone(cur realm, vaultIDStr string, milestoneIDStr string, evidenceURL string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusActive {
		panic("vault must be ACTIVE to submit a milestone")
	}
	caller := cur.Previous().Address()
	if caller != v.Builder {
		panic("only the assigned builder can submit milestone deliverables")
	}
	m := v.GetMilestone(parsePositiveInt(milestoneIDStr, "milestoneID"))
	if m == nil {
		panic("milestone not found")
	}
	if m.Status != MilestonePending {
		panic("milestone must be PENDING to submit")
	}
	evidenceURL = strings.TrimSpace(evidenceURL)
	if evidenceURL == "" {
		panic("evidence URL or proof hash cannot be empty")
	}

	m.Status = MilestoneSubmitted
	m.EvidenceURL = evidenceURL
	m.SubmittedAtHeight = runtime.ChainHeight()

	chain.Emit(
		"MilestoneSubmitted",
		"vault_id", strconv.Itoa(v.ID),
		"milestone_id", strconv.Itoa(m.ID),
		"builder", string(caller),
		"evidence", evidenceURL,
	)
}

// ApproveMilestone lets the sponsor approve a SUBMITTED milestone and atomically release ugnot
// from the vault's isolated sub-realm escrow directly to the builder.
func ApproveMilestone(cur realm, vaultIDStr string, milestoneIDStr string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusActive {
		panic("vault must be ACTIVE to approve milestones")
	}
	caller := cur.Previous().Address()
	if caller != v.Sponsor {
		panic("only the vault sponsor can approve a milestone")
	}
	m := v.GetMilestone(parsePositiveInt(milestoneIDStr, "milestoneID"))
	if m == nil {
		panic("milestone not found")
	}
	if m.Status != MilestoneSubmitted {
		panic("milestone must be SUBMITTED before approval")
	}

	releaseMilestoneToBuilder(cur, v, m)
}

// ClaimTimeoutRelease protects builders against unresponsive sponsors:
// once timeoutBlocks have elapsed since submission without approval or dispute,
// the builder can claim the milestone payout permissionlessly.
func ClaimTimeoutRelease(cur realm, vaultIDStr string, milestoneIDStr string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusActive {
		panic("vault must be ACTIVE to claim timeout release")
	}
	caller := cur.Previous().Address()
	if caller != v.Builder {
		panic("only the assigned builder can claim timeout release")
	}
	m := v.GetMilestone(parsePositiveInt(milestoneIDStr, "milestoneID"))
	if m == nil {
		panic("milestone not found")
	}
	if m.Status != MilestoneSubmitted {
		panic("milestone must be SUBMITTED to claim timeout release")
	}
	unlockHeight := m.SubmittedAtHeight + v.TimeoutBlocks
	if runtime.ChainHeight() < unlockHeight {
		panic("timeout not reached yet; unlocks at block " + strconv.FormatInt(unlockHeight, 10))
	}

	releaseMilestoneToBuilder(cur, v, m)
}

func releaseMilestoneToBuilder(cur realm, v *Vault, m *Milestone) {
	// Checks-Effects-Interactions: commit state updates before SendCoins.
	m.Status = MilestoneApproved
	m.ApprovedAtHeight = runtime.ChainHeight()
	v.ReleasedUgnot += m.AmountUgnot
	totalReleasedUgnot += m.AmountUgnot

	st := getOrCreateBuilderStats(v.Builder)
	st.MilestonesCompleted++
	st.TotalEarnedUgnot += m.AmountUgnot

	if v.AllMilestonesSettled() {
		v.Status = VaultStatusCompleted
		st.VaultsCompleted++
	}

	sub := cur.Sub(v.SubPath)
	subBanker := banker.NewBanker(banker.BankerTypeRealmSend, sub)
	subBanker.SendCoins(sub.Address(), v.Builder, chain.NewCoins(chain.NewCoin(DenomUGNOT, m.AmountUgnot)))

	chain.Emit(
		"MilestoneReleased",
		"vault_id", strconv.Itoa(v.ID),
		"milestone_id", strconv.Itoa(m.ID),
		"builder", string(v.Builder),
		"amount_ugnot", strconv.FormatInt(m.AmountUgnot, 10),
	)
}

// OpenDispute pauses a vault and escalates a SUBMITTED milestone to the arbiter council.
// Either the sponsor or the assigned builder may open a dispute.
func OpenDispute(cur realm, vaultIDStr string, milestoneIDStr string, reason string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusActive {
		panic("only ACTIVE vaults can enter dispute")
	}
	caller := cur.Previous().Address()
	if caller != v.Sponsor && caller != v.Builder {
		panic("only sponsor or assigned builder can open a dispute")
	}
	m := v.GetMilestone(parsePositiveInt(milestoneIDStr, "milestoneID"))
	if m == nil {
		panic("milestone not found")
	}
	if m.Status != MilestoneSubmitted {
		panic("only a SUBMITTED milestone can be disputed")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		panic("dispute reason cannot be empty")
	}

	v.Status = VaultStatusDisputed
	v.Dispute = &Dispute{
		Active:         true,
		MilestoneID:    m.ID,
		OpenedBy:       caller,
		Reason:         reason,
		OpenedAtHeight: runtime.ChainHeight(),
		QuorumRequired: escrowmath.QuorumThreshold(len(v.Arbiters)),
		Voted:          make(map[address]string),
	}

	chain.Emit(
		"DisputeOpened",
		"vault_id", strconv.Itoa(v.ID),
		"milestone_id", strconv.Itoa(m.ID),
		"opened_by", string(caller),
		"reason", reason,
	)
}

// VoteDispute lets an appointed arbiter cast one immutable vote: "RELEASE", "REFUND", or "SPLIT".
// Once strict majority quorum is reached (or all arbiters vote with deadlock fallback to SPLIT),
// the disputed milestone settles atomically from the isolated sub-realm escrow.
func VoteDispute(cur realm, vaultIDStr string, verdict string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusDisputed || v.Dispute == nil || !v.Dispute.Active {
		panic("vault does not have an active dispute")
	}
	caller := cur.Previous().Address()
	if !v.IsArbiter(caller) {
		panic("caller is not an appointed arbiter for this vault")
	}
	if _, already := v.Dispute.Voted[caller]; already {
		panic("arbiter already voted on this dispute")
	}

	verdict = strings.ToUpper(strings.TrimSpace(verdict))
	switch verdict {
	case VoteRelease:
		v.Dispute.VotesRelease++
	case VoteRefund:
		v.Dispute.VotesRefund++
	case VoteSplit:
		v.Dispute.VotesSplit++
	default:
		panic("verdict must be RELEASE, REFUND, or SPLIT")
	}
	v.Dispute.Voted[caller] = verdict

	chain.Emit(
		"DisputeVoted",
		"vault_id", strconv.Itoa(v.ID),
		"arbiter", string(caller),
		"verdict", verdict,
	)

	outcome, reached := escrowmath.EvaluateDisputeTally(
		v.Dispute.VotesRelease,
		v.Dispute.VotesRefund,
		v.Dispute.VotesSplit,
		len(v.Arbiters),
	)
	if !reached {
		return
	}

	// Settle dispute atomically.
	m := v.GetMilestone(v.Dispute.MilestoneID)
	v.Dispute.Active = false
	v.Dispute.ResolvedOutcome = outcome

	st := getOrCreateBuilderStats(v.Builder)
	sub := cur.Sub(v.SubPath)
	subBanker := banker.NewBanker(banker.BankerTypeRealmSend, sub)

	switch outcome {
	case VoteRelease:
		m.Status = MilestoneApproved
		m.ApprovedAtHeight = runtime.ChainHeight()
		v.ReleasedUgnot += m.AmountUgnot
		totalReleasedUgnot += m.AmountUgnot
		st.MilestonesCompleted++
		st.TotalEarnedUgnot += m.AmountUgnot
		st.DisputesWon++
		if v.AllMilestonesSettled() {
			v.Status = VaultStatusCompleted
			st.VaultsCompleted++
		} else {
			v.Status = VaultStatusActive
		}
		subBanker.SendCoins(sub.Address(), v.Builder, chain.NewCoins(chain.NewCoin(DenomUGNOT, m.AmountUgnot)))

	case VoteRefund:
		m.Status = MilestoneRefunded
		v.RefundedUgnot += m.AmountUgnot
		totalRefundedUgnot += m.AmountUgnot
		st.DisputesLost++
		if v.AllMilestonesSettled() {
			v.Status = VaultStatusCompleted
		} else {
			v.Status = VaultStatusActive
		}
		subBanker.SendCoins(sub.Address(), v.Sponsor, chain.NewCoins(chain.NewCoin(DenomUGNOT, m.AmountUgnot)))

	case VoteSplit:
		builderAmt, sponsorAmt := escrowmath.ComputeSplit(m.AmountUgnot)
		m.Status = MilestoneSplit
		m.ApprovedAtHeight = runtime.ChainHeight()
		v.ReleasedUgnot += builderAmt
		v.RefundedUgnot += sponsorAmt
		totalReleasedUgnot += builderAmt
		totalRefundedUgnot += sponsorAmt
		st.TotalEarnedUgnot += builderAmt
		if v.AllMilestonesSettled() {
			v.Status = VaultStatusCompleted
		} else {
			v.Status = VaultStatusActive
		}
		if builderAmt > 0 {
			subBanker.SendCoins(sub.Address(), v.Builder, chain.NewCoins(chain.NewCoin(DenomUGNOT, builderAmt)))
		}
		if sponsorAmt > 0 {
			subBanker.SendCoins(sub.Address(), v.Sponsor, chain.NewCoins(chain.NewCoin(DenomUGNOT, sponsorAmt)))
		}
	}

	chain.Emit(
		"DisputeResolved",
		"vault_id", strconv.Itoa(v.ID),
		"milestone_id", strconv.Itoa(m.ID),
		"outcome", outcome,
	)
}

// CancelVault allows the sponsor to cancel an OPEN (unassigned) vault and reclaim 100%
// of the escrowed ugnot from the isolated sub-realm account.
func CancelVault(cur realm, vaultIDStr string) {
	realmPkgPath = cur.PkgPath()
	v := mustGetVault(parsePositiveInt(vaultIDStr, "vaultID"))
	if v.Status != VaultStatusOpen {
		panic("only OPEN (unassigned) vaults can be cancelled")
	}
	caller := cur.Previous().Address()
	if caller != v.Sponsor {
		panic("only the vault sponsor can cancel an open vault")
	}

	refundAmt := v.LockedAmount()
	v.Status = VaultStatusCancelled
	for _, m := range v.Milestones {
		m.Status = MilestoneRefunded
	}
	v.RefundedUgnot += refundAmt
	totalRefundedUgnot += refundAmt

	if refundAmt > 0 {
		sub := cur.Sub(v.SubPath)
		subBanker := banker.NewBanker(banker.BankerTypeRealmSend, sub)
		subBanker.SendCoins(sub.Address(), v.Sponsor, chain.NewCoins(chain.NewCoin(DenomUGNOT, refundAmt)))
	}

	chain.Emit(
		"VaultCancelled",
		"vault_id", strconv.Itoa(v.ID),
		"sponsor", string(v.Sponsor),
		"refund_ugnot", strconv.FormatInt(refundAmt, 10),
	)
}

// VaultCount returns total number of created vaults (read-only helper for composability).
func VaultCount() int {
	return len(vaults)
}

// GetVaultEscrowAddress returns the isolated cur.Sub escrow address for vaultID.
func GetVaultEscrowAddress(vaultID int) address {
	return mustGetVault(vaultID).EscrowAddr
}

func mustGetVault(id int) *Vault {
	if id < 1 || id > len(vaults) {
		panic("vault not found: " + strconv.Itoa(id))
	}
	return vaults[id-1]
}

