package aegis_core

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strings"
)

// A duel is 3 rounds. Each fighter commits a 3-letter move string such as
// "SGF" before the commit deadline. Triangle: Strike > Feint > Guard > Strike.
const (
	Rounds     = 3
	StartHP    = 100
	RoundDmg   = 34
	ChipDmg    = 8 // both chose the same move: both take chip damage
	MoveStrike = "S"
	MoveGuard  = "G"
	MoveFeint  = "F"
)

var (
	ErrBadMoves = errors.New("aegis: moves must be exactly 3 of S/G/F")
	ErrBadSalt  = errors.New("aegis: salt must be 8..64 chars")
)

// CommitHash = hex(sha256(moves + ":" + salt)).
func CommitHash(moves, salt string) string {
	sum := sha256.Sum256([]byte(moves + ":" + salt))
	return hex.EncodeToString(sum[:])
}

// VerifyReveal checks that (moves, salt) opens the commitment and the moves are legal.
func VerifyReveal(commit, moves, salt string) error {
	if err := ValidateMoves(moves); err != nil {
		return err
	}
	if len(salt) < 8 || len(salt) > 64 {
		return ErrBadSalt
	}
	if CommitHash(moves, salt) != strings.ToLower(commit) {
		return errors.New("aegis: reveal does not match commitment")
	}
	return nil
}

func ValidateMoves(moves string) error {
	if len(moves) != Rounds {
		return ErrBadMoves
	}
	for i := 0; i < len(moves); i++ {
		c := string(moves[i])
		if c != MoveStrike && c != MoveGuard && c != MoveFeint {
			return ErrBadMoves
		}
	}
	return nil
}

// Beats reports whether move a beats move b.
func Beats(a, b string) bool {
	return (a == MoveStrike && b == MoveFeint) ||
		(a == MoveFeint && b == MoveGuard) ||
		(a == MoveGuard && b == MoveStrike)
}

// RoundResult is one line of the combat log.
type RoundResult struct {
	MoveA, MoveB string
	HPA, HPB     int
}

// ResolveDuel is fully deterministic: same inputs, same outcome, on every node.
// winner: 1 = A, 2 = B, 0 = draw.
func ResolveDuel(movesA, movesB string) (winner int, log []RoundResult) {
	hpA, hpB := StartHP, StartHP
	for i := 0; i < Rounds; i++ {
		a, b := string(movesA[i]), string(movesB[i])
		switch {
		case a == b:
			hpA -= ChipDmg
			hpB -= ChipDmg
		case Beats(a, b):
			hpB -= RoundDmg
		default:
			hpA -= RoundDmg
		}
		if hpA < 0 {
			hpA = 0
		}
		if hpB < 0 {
			hpB = 0
		}
		log = append(log, RoundResult{MoveA: a, MoveB: b, HPA: hpA, HPB: hpB})
	}
	switch {
	case hpA > hpB:
		winner = 1
	case hpB > hpA:
		winner = 2
	}
	return winner, log
}

func MoveName(m string) string {
	switch m {
	case MoveStrike:
		return "Strike"
	case MoveGuard:
		return "Guard"
	case MoveFeint:
		return "Feint"
	}
	return "?"
}

// Package aegis_core is the reusable, stateless core of Aegis Pit.
//
// It contains no realm state, so any realm can import it:
//   - Policy / ValidateSpend: hard spending rules for AI agents
//   - CommitHash / VerifyReveal / ResolveDuel: commit-reveal duel engine
//   - TrustRecord / TrustScore: reputation tied to real money at stake
//   - SplitPool: deterministic 95/3/2 pool split
package aegis_core

import (
	"errors"
	"strings"
)

var (
	ErrNoTargets      = errors.New("aegis: policy needs at least one allowed target")
	ErrBadTarget      = errors.New("aegis: invalid target address in policy")
	ErrBadCap         = errors.New("aegis: maxPerTx must be > 0")
	ErrExpired        = errors.New("aegis: policy expired")
	ErrTargetDenied   = errors.New("aegis: target not in allowlist")
	ErrFnDenied       = errors.New("aegis: function not in allowlist")
	ErrOverCap        = errors.New("aegis: amount exceeds per-tx cap")
	ErrNonPositiveAmt = errors.New("aegis: amount must be > 0")
)

// Policy is a spending rulebook signed by a human owner.
// Whatever an AI agent "decides" (or is prompt-injected into deciding),
// a spend only goes through if it satisfies every rule here.
type Policy struct {
	Targets      []address // allowed recipient addresses
	Fns          []string  // allowed function labels ("*" = any)
	MaxPerTx     int64     // ugnot cap per spend
	ExpireHeight int64     // 0 = never expires
}

// NewPolicy builds a Policy from comma-separated lists (friendly for
// `gnokey maketx call` and gnoweb forms).
func NewPolicy(targetsCSV, fnsCSV string, maxPerTx, expireHeight int64) (*Policy, error) {
	if maxPerTx <= 0 {
		return nil, ErrBadCap
	}
	targets := []address{}
	for _, raw := range splitCSV(targetsCSV) {
		a := address(raw)
		if !a.IsValid() {
			return nil, ErrBadTarget
		}
		targets = append(targets, a)
	}
	if len(targets) == 0 {
		return nil, ErrNoTargets
	}
	fns := splitCSV(fnsCSV)
	if len(fns) == 0 {
		fns = []string{"*"}
	}
	return &Policy{Targets: targets, Fns: fns, MaxPerTx: maxPerTx, ExpireHeight: expireHeight}, nil
}

// ValidateSpend returns nil only if the spend respects the policy.
// Callers are expected to panic on error so the whole tx reverts.
func ValidateSpend(p *Policy, target address, fn string, amt int64, height int64) error {
	if amt <= 0 {
		return ErrNonPositiveAmt
	}
	if p.ExpireHeight > 0 && height > p.ExpireHeight {
		return ErrExpired
	}
	if amt > p.MaxPerTx {
		return ErrOverCap
	}
	if !p.AllowsTarget(target) {
		return ErrTargetDenied
	}
	if !p.AllowsFn(fn) {
		return ErrFnDenied
	}
	return nil
}

func (p *Policy) AllowsTarget(target address) bool {
	for _, t := range p.Targets {
		if t == target {
			return true
		}
	}
	return false
}

func (p *Policy) AllowsFn(fn string) bool {
	for _, f := range p.Fns {
		if f == "*" || f == fn {
			return true
		}
	}
	return false
}

func splitCSV(s string) []string {
	out := []string{}
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

package aegis_core

// TrustRecord only counts matches where real ugnot was at stake.
// Friendly matches never touch it, so reputation cannot be farmed for free.
type TrustRecord struct {
	RankedWins   int64
	RankedLosses int64
	Forfeits     int64 // committed but never revealed: bond slashed
	StakedVolume int64 // total ugnot bet on this fighter's matches
}

// TrustScore turns a record into a 0..1000 score.
//
//	base   = 500
//	+ 25 per ranked win, -10 per ranked loss
//	- 150 per forfeit (match-fixing signal)
//	+ 1 per 1 GNOT (1_000_000 ugnot) of staked volume, capped at +200
func TrustScore(r TrustRecord) int64 {
	s := int64(500)
	s += 25 * r.RankedWins
	s -= 10 * r.RankedLosses
	s -= 150 * r.Forfeits
	vol := r.StakedVolume / 1_000_000
	if vol > 200 {
		vol = 200
	}
	s += vol
	if s < 0 {
		s = 0
	}
	if s > 1000 {
		s = 1000
	}
	return s
}

// Pool split in basis points.
const (
	WinnersBps = 9500
	BackersBps = 300
	SeasonBps  = 200
)

// SplitPool splits a pool 95/3/2. Rounding dust goes to winners so
// winners+backers+season == total, always.
func SplitPool(total int64) (winners, backers, season int64) {
	backers = total * BackersBps / 10000
	season = total * SeasonBps / 10000
	winners = total - backers - season
	return
}

// ProRata returns stake * pot / totalStake (0 if totalStake == 0).
func ProRata(stake, pot, totalStake int64) int64 {
	if totalStake == 0 {
		return 0
	}
	return stake * pot / totalStake
}

package aegis_pit

import (
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
	"gno.land/p/nt/avl/v0"
)

// ======================= Fighters & Backer Tokens =======================

const shareScale int64 = 1_000_000

// BackerLedger is a GRC20-style fungible ledger of "Backer Tokens" for one
// fighter. Holders earn 3% of every ranked pool their fighter wins, using a
// reward-per-share accumulator (O(1) per payout, no loops over holders).
type BackerLedger struct {
	Symbol      string
	Supply      int64
	balances    *avl.Tree // addr -> int64
	debt        *avl.Tree // addr -> int64 (already-accounted rewards)
	accPerShare int64     // scaled by shareScale
	Distributed int64
}

func (l *BackerLedger) BalanceOf(a address) int64 {
	v := l.balances.Get(string(a))
	if v == nil {
		return 0
	}
	return v.(int64)
}

func (l *BackerLedger) debtOf(a address) int64 {
	v := l.debt.Get(string(a))
	if v == nil {
		return 0
	}
	return v.(int64)
}

func (l *BackerLedger) Pending(a address) int64 {
	return l.BalanceOf(a)*l.accPerShare/shareScale - l.debtOf(a)
}

// settle moves pending rewards to the holder's claimable credits.
func (l *BackerLedger) settle(a address) {
	addCredit(a, l.Pending(a))
	l.debt.Set(string(a), l.BalanceOf(a)*l.accPerShare/shareScale)
}

func (l *BackerLedger) reward(amt int64) int64 {
	if amt <= 0 || l.Supply == 0 {
		return 0
	}
	inc := amt * shareScale / l.Supply
	l.accPerShare += inc
	paid := inc * l.Supply / shareScale
	l.Distributed += paid
	return amt - paid // dust
}

func (l *BackerLedger) transfer(from, to address, amt int64) {
	if amt <= 0 || l.BalanceOf(from) < amt {
		panic("aegis: insufficient backer tokens")
	}
	l.settle(from)
	l.settle(to)
	l.balances.Set(string(from), l.BalanceOf(from)-amt)
	l.balances.Set(string(to), l.BalanceOf(to)+amt)
	l.debt.Set(string(from), l.BalanceOf(from)*l.accPerShare/shareScale)
	l.debt.Set(string(to), l.BalanceOf(to)*l.accPerShare/shareScale)
}

type Fighter struct {
	ID       int
	Name     string
	PkgPath  string // public Gno source of the fighter's strategy (read by rival AIs via gnomcp)
	Owner    address
	Agent    address // optional AI agent key allowed to commit/reveal
	Backers  *BackerLedger
	Wins     int
	Losses   int
	Draws    int
	Forfeits int
	Badges   []string
}

func getFighter(id int) *Fighter {
	v := fighters.Get(key(id))
	if v == nil {
		panic("aegis: fighter not found")
	}
	return v.(*Fighter)
}

func (f *Fighter) controls(a address) bool {
	return a == f.Owner || (f.Agent != "" && a == f.Agent)
}

// RegisterFighter registers an AI fighter and mints its Backer Tokens to the owner.
func RegisterFighter(cur realm, name, pkgPath string, backerSupply int64) int {
	if len(name) == 0 || len(name) > 24 {
		panic("aegis: name must be 1..24 chars")
	}
	if backerSupply < 1 || backerSupply > 1_000_000_000 {
		panic("aegis: backerSupply must be 1..1e9")
	}
	owner := caller(cur)
	nFighters++
	l := &BackerLedger{
		Symbol:   "BACK" + strconv.Itoa(nFighters),
		Supply:   backerSupply,
		balances: avl.NewTree(),
		debt:     avl.NewTree(),
	}
	l.balances.Set(string(owner), backerSupply)
	f := &Fighter{ID: nFighters, Name: name, PkgPath: pkgPath, Owner: owner, Backers: l}
	fighters.Set(key(f.ID), f)
	return f.ID
}

// SetFighterAgent authorizes an AI agent key (e.g. a gnomcp session) to commit/reveal.
func SetFighterAgent(cur realm, fighterID int, agent address) {
	f := getFighter(fighterID)
	if caller(cur) != f.Owner {
		panic("aegis: only the owner can set the agent")
	}
	f.Agent = agent
}

// TransferBacker transfers Backer Tokens of a fighter (rewards are settled first).
func TransferBacker(cur realm, fighterID int, to address, amount int64) {
	if !to.IsValid() {
		panic("aegis: invalid recipient")
	}
	getFighter(fighterID).Backers.transfer(caller(cur), to, amount)
}

// ClaimBackerRewards moves pending backer dividends into claimable credits.
func ClaimBackerRewards(cur realm, fighterID int) {
	getFighter(fighterID).Backers.settle(caller(cur))
}

func BackerBalance(fighterID int, a address) int64 { return getFighter(fighterID).Backers.BalanceOf(a) }
func BackerPending(fighterID int, a address) int64 { return getFighter(fighterID).Backers.Pending(a) }

// ======================= Trust =======================

func trustOf(a address) *core.TrustRecord {
	v := trust.Get(string(a))
	if v == nil {
		r := &core.TrustRecord{}
		trust.Set(string(a), r)
		return r
	}
	return v.(*core.TrustRecord)
}

// TrustScore is exported for other realms to import: reputation that only
// moves when real ugnot was at stake.
func TrustScore(a address) int64 {
	v := trust.Get(string(a))
	if v == nil {
		return core.TrustScore(core.TrustRecord{})
	}
	return core.TrustScore(*v.(*core.TrustRecord))
}

// ======================= Matches =======================

const (
	StatusOpen     = "open"     // waiting for opponent
	StatusLive     = "live"     // commits + bets open until CommitDeadline
	StatusResolved = "resolved" // both revealed
	StatusForfeit  = "forfeit"  // someone did not reveal: bond slashed
	StatusCanceled = "canceled"
)

type Match struct {
	ID             int
	Ranked         bool
	A, B           int // fighter IDs (B = 0 while open)
	Bond           int64
	CommitDeadline int64
	RevealDeadline int64
	CommitA        string
	CommitB        string
	MovesA         string
	MovesB         string
	Status         string
	Winner         int // 0 draw, 1 = A, 2 = B
	betsA          *avl.Tree
	betsB          *avl.Tree
	PoolA          int64
	PoolB          int64
	Log            []core.RoundResult
	Note           string
}

func getMatch(id int) *Match {
	v := matches.Get(key(id))
	if v == nil {
		panic("aegis: match not found")
	}
	return v.(*Match)
}

// CreateMatch opens a match for one of your fighters. Attach the bond in ugnot.
// ranked=false is a friendly match (no betting, no trust impact).
func CreateMatch(cur realm, fighterID int, ranked bool) int {
	bond := takeDeposit(cur)
	if bond < MinBond {
		panic("aegis: bond below minimum (" + strconv.FormatInt(MinBond, 10) + " ugnot)")
	}
	f := getFighter(fighterID)
	if !f.controls(caller(cur)) {
		panic("aegis: you do not control this fighter")
	}
	nMatches++
	m := &Match{ID: nMatches, Ranked: ranked, A: fighterID, Bond: bond, Status: StatusOpen,
		betsA: avl.NewTree(), betsB: avl.NewTree()}
	matches.Set(key(m.ID), m)
	return m.ID
}

// CancelMatch refunds the creator's bond while nobody has joined yet.
func CancelMatch(cur realm, matchID int) {
	m := getMatch(matchID)
	f := getFighter(m.A)
	if m.Status != StatusOpen || !f.controls(caller(cur)) {
		panic("aegis: only the creator can cancel an open match")
	}
	m.Status = StatusCanceled
	addCredit(f.Owner, m.Bond)
}

// JoinMatch joins with your fighter, attaching exactly the same bond.
// The commit deadline (and betting lock) is set at this block.
func JoinMatch(cur realm, matchID, fighterID int) {
	amt := takeDeposit(cur)
	m := getMatch(matchID)
	if m.Status != StatusOpen {
		panic("aegis: match is not open")
	}
	if amt != m.Bond {
		panic("aegis: bond must equal " + strconv.FormatInt(m.Bond, 10) + " ugnot")
	}
	fa := getFighter(m.A)
	fb := getFighter(fighterID)
	if !fb.controls(caller(cur)) {
		panic("aegis: you do not control this fighter")
	}
	if fa.Owner == fb.Owner {
		panic("aegis: cannot fight yourself")
	}
	m.B = fighterID
	m.Status = StatusLive
	m.CommitDeadline = height() + CommitWindow
	m.RevealDeadline = m.CommitDeadline + RevealWindow
}

// PlaceBet bets the attached ugnot on side 1 (A) or 2 (B) of a ranked, live match.
func PlaceBet(cur realm, matchID, side int) {
	amt := takeDeposit(cur)
	placeBet(getMatch(matchID), caller(cur), side, amt)
}

func placeBet(m *Match, bettor address, side int, amt int64) {
	if !m.Ranked {
		panic("aegis: friendly matches have no betting")
	}
	if m.Status != StatusLive || height() > m.CommitDeadline {
		panic("aegis: betting is locked")
	}
	if side != 1 && side != 2 {
		panic("aegis: side must be 1 or 2")
	}
	if amt < MinBet {
		panic("aegis: bet too small")
	}
	// Anti match-fixing: an owner can never bet against their own fighter.
	if (side == 2 && getFighter(m.A).Owner == bettor) || (side == 1 && getFighter(m.B).Owner == bettor) {
		panic("aegis: owners cannot bet against their own fighter")
	}
	t := m.betsA
	if side == 2 {
		t = m.betsB
	}
	prev := int64(0)
	if v := t.Get(string(bettor)); v != nil {
		prev = v.(int64)
	}
	t.Set(string(bettor), prev+amt)
	if side == 1 {
		m.PoolA += amt
	} else {
		m.PoolB += amt
	}
}

// CommitMove stores hash(moves:salt) — see aegis_core.CommitHash.
func CommitMove(cur realm, matchID int, commit string) {
	m := getMatch(matchID)
	if m.Status != StatusLive || height() > m.CommitDeadline {
		panic("aegis: commit window closed")
	}
	if len(commit) != 64 {
		panic("aegis: commit must be a 64-char sha256 hex")
	}
	who := caller(cur)
	switch {
	case getFighter(m.A).controls(who):
		if m.CommitA != "" {
			panic("aegis: already committed")
		}
		m.CommitA = commit
	case getFighter(m.B).controls(who):
		if m.CommitB != "" {
			panic("aegis: already committed")
		}
		m.CommitB = commit
	default:
		panic("aegis: not a fighter in this match")
	}
}

// Reveal opens your commitment. Only allowed after the commit deadline (so
// nobody — fighter or bettor — sees a move while bets are open). When both
// sides have revealed, the match resolves and pays out automatically.
func Reveal(cur realm, matchID int, moves, salt string) {
	m := getMatch(matchID)
	if m.Status != StatusLive {
		panic("aegis: match not live")
	}
	h := height()
	if h <= m.CommitDeadline {
		panic("aegis: reveal opens after block " + strconv.FormatInt(m.CommitDeadline, 10))
	}
	if h > m.RevealDeadline {
		panic("aegis: reveal window closed, use SlashNoReveal")
	}
	who := caller(cur)
	switch {
	case getFighter(m.A).controls(who) && m.MovesA == "":
		if err := core.VerifyReveal(m.CommitA, moves, salt); err != nil {
			panic(err.Error())
		}
		m.MovesA = moves
	case getFighter(m.B).controls(who) && m.MovesB == "":
		if err := core.VerifyReveal(m.CommitB, moves, salt); err != nil {
			panic(err.Error())
		}
		m.MovesB = moves
	default:
		panic("aegis: nothing to reveal for caller")
	}
	if m.MovesA != "" && m.MovesB != "" {
		resolve(m)
	}
}

func resolve(m *Match) {
	fa, fb := getFighter(m.A), getFighter(m.B)
	m.Winner, m.Log = core.ResolveDuel(m.MovesA, m.MovesB)
	m.Status = StatusResolved
	addCredit(fa.Owner, m.Bond)
	addCredit(fb.Owner, m.Bond)

	switch m.Winner {
	case 0:
		fa.Draws++
		fb.Draws++
	case 1:
		fa.Wins++
		fb.Losses++
	case 2:
		fb.Wins++
		fa.Losses++
	}

	total := m.PoolA + m.PoolB
	if !m.Ranked {
		m.Note = "friendly match: no pool, no trust change"
		awardBadges(m)
		return
	}
	if m.Winner == 0 {
		refundBets(m)
		m.Note = "draw: all bets refunded"
		return
	}
	winPool, winBets, wf, lf := m.PoolA, m.betsA, fa, fb
	if m.Winner == 2 {
		winPool, winBets, wf, lf = m.PoolB, m.betsB, fb, fa
	}
	tw := trustOf(wf.Owner)
	tl := trustOf(lf.Owner)
	tw.RankedWins++
	tl.RankedLosses++
	tw.StakedVolume += total
	tl.StakedVolume += total

	if winPool == 0 {
		refundBets(m)
		m.Note = "nobody backed the winner: all bets refunded"
		awardBadges(m)
		return
	}
	winners, backers, season := core.SplitPool(total)
	paid := int64(0)
	winBets.Iterate("", "", func(k string, v any) bool {
		share := core.ProRata(v.(int64), winners, winPool)
		addCredit(address(k), share)
		paid += share
		return false
	})
	dust := winners - paid
	dust += wf.Backers.reward(backers)
	seasonFund += season + dust
	m.Note = "pool " + strconv.FormatInt(total, 10) + " ugnot: 95% bettors / 3% backers of " + wf.Name + " / 2% season"
	awardBadges(m)
}

func refundBets(m *Match) {
	refund := func(k string, v any) bool {
		addCredit(address(k), v.(int64))
		return false
	}
	m.betsA.Iterate("", "", refund)
	m.betsB.Iterate("", "", refund)
}

func awardBadges(m *Match) {
	if m.Winner == 0 || len(m.Log) == 0 {
		return
	}
	last := m.Log[len(m.Log)-1]
	w, hp, underdog := getFighter(m.A), last.HPA, m.PoolA < m.PoolB
	if m.Winner == 2 {
		w, hp, underdog = getFighter(m.B), last.HPB, m.PoolB < m.PoolA
	}
	if w.Wins == 1 {
		w.Badges = append(w.Badges, "First Blood")
	}
	if hp == core.StartHP {
		w.Badges = append(w.Badges, "Untouched")
	}
	if m.Ranked && underdog {
		w.Badges = append(w.Badges, "Giant Slayer")
	}
	if w.Wins == 5 {
		w.Badges = append(w.Badges, "Pit Veteran")
	}
}

// SlashNoReveal can be called by anyone after the reveal deadline.
// A fighter who did not reveal loses its bond to the opponent; bettors are refunded.
// If neither revealed, both bonds go to the season fund.
func SlashNoReveal(cur realm, matchID int) {
	m := getMatch(matchID)
	if m.Status != StatusLive || height() <= m.RevealDeadline {
		panic("aegis: nothing to slash yet")
	}
	fa, fb := getFighter(m.A), getFighter(m.B)
	refundBets(m)
	m.Status = StatusForfeit
	id := "match #" + strconv.Itoa(m.ID)
	switch {
	case m.MovesA != "" && m.MovesB == "":
		m.Winner = 1
		addCredit(fa.Owner, 2*m.Bond)
		fb.Forfeits++
		fa.Wins++
		if m.Ranked {
			trustOf(fb.Owner).Forfeits++
		}
		logLab("slash", id+": "+fb.Name+" never revealed, bond "+strconv.FormatInt(m.Bond, 10)+" → "+fa.Name)
	case m.MovesB != "" && m.MovesA == "":
		m.Winner = 2
		addCredit(fb.Owner, 2*m.Bond)
		fa.Forfeits++
		fb.Wins++
		if m.Ranked {
			trustOf(fa.Owner).Forfeits++
		}
		logLab("slash", id+": "+fa.Name+" never revealed, bond "+strconv.FormatInt(m.Bond, 10)+" → "+fb.Name)
	default:
		seasonFund += 2 * m.Bond
		fa.Forfeits++
		fb.Forfeits++
		if m.Ranked {
			trustOf(fa.Owner).Forfeits++
			trustOf(fb.Owner).Forfeits++
		}
		logLab("slash", id+": neither fighter revealed, both bonds → season fund")
	}
	m.Note = "forfeit: bettors refunded"
}

// Read helpers
func MatchStatus(matchID int) string { return getMatch(matchID).Status }
func MatchWinner(matchID int) int    { return getMatch(matchID).Winner }

package aegis_pit

import (
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
)

// Box is a budget a human locks for an AI agent.
// The agent can only move funds inside the Policy; the owner can always exit.
type Box struct {
	ID      int
	Owner   address
	Agent   address
	Policy  *core.Policy
	Balance int64
	Spent   int64
	Blocked int
	Closed  bool
}

func getBox(id int) *Box {
	v := boxes.Get(key(id))
	if v == nil {
		panic("aegis: box not found")
	}
	return v.(*Box)
}

// CreateBox locks the attached ugnot under a spending policy.
// allowedTargets / allowedFns are comma-separated; allowedFns "" means any.
// Use this realm's address as a target + fn "PlaceBet" to let the agent bet via BoxBet.
func CreateBox(cur realm, agent address, allowedTargets, allowedFns string, maxPerTx, expireHeight int64) int {
	amt := takeDeposit(cur)
	if amt <= 0 {
		panic("aegis: attach ugnot to fund the box")
	}
	p, err := core.NewPolicy(allowedTargets, allowedFns, maxPerTx, expireHeight)
	if err != nil {
		panic(err.Error())
	}
	nBoxes++
	b := &Box{ID: nBoxes, Owner: caller(cur), Agent: agent, Policy: p, Balance: amt}
	boxes.Set(key(b.ID), b)
	return b.ID
}

// TopUpBox adds the attached ugnot to an open box (owner only).
func TopUpBox(cur realm, boxID int) {
	amt := takeDeposit(cur)
	b := getBox(boxID)
	if caller(cur) != b.Owner || b.Closed {
		panic("aegis: only the owner can top up an open box")
	}
	b.Balance += amt
}

func checkBoxSpend(b *Box, who address, target address, fn string, amount int64) error {
	if b.Closed {
		return errBox("box closed")
	}
	if who != b.Owner && who != b.Agent {
		return errBox("caller is not the box owner or its agent")
	}
	if err := core.ValidateSpend(b.Policy, target, fn, amount, height()); err != nil {
		return err
	}
	if amount > b.Balance {
		return errBox("insufficient box balance")
	}
	return nil
}

// BoxSpend sends ugnot from the box to target. Any policy violation panics,
// so the whole transaction reverts on-chain.
func BoxSpend(cur realm, boxID int, target address, fn string, amount int64) {
	b := getBox(boxID)
	if err := checkBoxSpend(b, caller(cur), target, fn, amount); err != nil {
		panic(err.Error())
	}
	b.Balance -= amount
	b.Spent += amount
	send(cur, target, amount)
}

// GuardedSpend is the "soft" variant used by the Breaker Lab: instead of
// reverting, a violation is recorded publicly and no coin moves.
func GuardedSpend(cur realm, boxID int, target address, fn string, amount int64) bool {
	b := getBox(boxID)
	if err := checkBoxSpend(b, caller(cur), target, fn, amount); err != nil {
		b.Blocked++
		logLab("blocked", "box #"+strconv.Itoa(boxID)+" → "+string(target)+" "+fn+"("+strconv.FormatInt(amount, 10)+" ugnot): "+err.Error())
		return false
	}
	b.Balance -= amount
	b.Spent += amount
	send(cur, target, amount)
	return true
}

// BoxBet lets an agent bet from a box. The policy must allow this realm's
// address as target and "PlaceBet" as fn. The bet belongs to the box owner.
func BoxBet(cur realm, boxID, matchID, side int, amount int64) {
	b := getBox(boxID)
	if err := checkBoxSpend(b, caller(cur), cur.Address(), "PlaceBet", amount); err != nil {
		panic(err.Error())
	}
	b.Balance -= amount
	b.Spent += amount
	placeBet(getMatch(matchID), b.Owner, side, amount)
}

// LogPreflight lets a box owner/agent publish a pre-flight report (qeval/qrender summary).
func LogPreflight(cur realm, boxID int, report string) {
	b := getBox(boxID)
	who := caller(cur)
	if who != b.Owner && who != b.Agent {
		panic("aegis: only the box owner or agent can log preflight")
	}
	if len(report) > 280 {
		report = report[:280]
	}
	logLab("preflight", "box #"+strconv.Itoa(boxID)+": "+report)
}

// EmergencyWithdraw returns the whole box balance to the owner and closes it.
// Reachable straight from gnoweb via Render("exit"); no external website needed.
func EmergencyWithdraw(cur realm, boxID int) int64 {
	b := getBox(boxID)
	if caller(cur) != b.Owner {
		panic("aegis: only the box owner can withdraw")
	}
	amt := b.Balance
	b.Balance = 0
	b.Closed = true
	send(cur, b.Owner, amt)
	logLab("exit", "box #"+strconv.Itoa(boxID)+" emergency-withdrawn: "+strconv.FormatInt(amt, 10)+" ugnot")
	return amt
}

// BoxBalance is a read helper.
func BoxBalance(boxID int) int64 { return getBox(boxID).Balance }

type boxErr struct{ msg string }

func (e boxErr) Error() string { return "aegis: " + e.msg }

func errBox(msg string) error { return boxErr{msg} }

package aegis_pit

import (
	"strconv"
	"strings"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
)

// Render serves 5 gnoweb screens:
//
//	""            arena lobby
//	"match/<id>"  duel board + combat log
//	"fighters"    leaderboard, trust, backer tokens, badges
//	"lab"         breaker lab: blocked attacks, slashes, preflight reports
//	"exit"        emergency exit (plain text + direct withdraw links)
func Render(path string) string {
	switch {
	case path == "":
		return renderLobby()
	case strings.HasPrefix(path, "match/"):
		id, err := strconv.Atoi(strings.TrimPrefix(path, "match/"))
		if err != nil || matches.Get(key(id)) == nil {
			return "# 404\nMatch not found. [Back to lobby](" + linkPath() + ")"
		}
		return renderMatch(getMatch(id))
	case path == "fighters":
		return renderFighters()
	case path == "lab":
		return renderLab()
	case path == "exit":
		return renderExit()
	}
	return "# 404\n[Back to lobby](" + linkPath() + ")"
}

func nav() string {
	p := linkPath()
	return "[Arena](" + p + ") · [Fighters](" + p + ":fighters) · [Breaker Lab](" + p + ":lab) · [Emergency Exit](" + p + ":exit)\n\n"
}

func renderLobby() string {
	out := "# ⚔️ Aegis Pit\n" + nav()
	out += "Oracle-free prediction market on deterministic AI duels. Commit-reveal locks moves **and** bets at the same block; no-shows lose their bond.\n\n"
	out += "**Block:** " + strconv.FormatInt(height(), 10) + " · **Season fund:** " + strconv.FormatInt(seasonFund, 10) + " ugnot · "
	out += "[Register fighter](" + txLink("RegisterFighter") + ") · [Create match](" + txLink("CreateMatch") + ") · [Claim winnings](" + txLink("Claim") + ")\n\n"
	if matches.Size() == 0 {
		return out + "_No matches yet. Register a fighter and open one._\n"
	}
	out += "## Matches\n\n"
	count := 0
	matches.ReverseIterate("", "", func(k string, v any) bool {
		m := v.(*Match)
		out += "[" + matchCardSVG(m) + "](" + linkPath() + ":match/" + itoa(m.ID) + ")\n\n"
		count++
		return count >= 10
	})
	return out
}

func renderMatch(m *Match) string {
	id := itoa(m.ID)
	fa := getFighter(m.A)
	out := "# Match #" + id + "\n" + nav() + matchCardSVG(m) + "\n\n"
	out += "| | " + fa.Name + " (A)"
	nameB := "—"
	if m.B != 0 {
		nameB = getFighter(m.B).Name
	}
	out += " | " + nameB + " (B) |\n|---|---|---|\n"
	out += "| Commit | " + yesNo(m.CommitA != "") + " | " + yesNo(m.CommitB != "") + " |\n"
	out += "| Reveal | " + orDash(m.MovesA) + " | " + orDash(m.MovesB) + " |\n"
	out += "| Pool (ugnot) | " + strconv.FormatInt(m.PoolA, 10) + " | " + strconv.FormatInt(m.PoolB, 10) + " |\n\n"
	out += "**Mode:** " + modeLabel(m) + " · **Bond:** " + strconv.FormatInt(m.Bond, 10) + " ugnot · **Phase:** " + phase(m) + "\n\n"

	switch m.Status {
	case StatusOpen:
		out += "[Join this match](" + txLink("JoinMatch", "matchID", id) + ") (attach exactly the bond)\n"
	case StatusLive:
		if height() <= m.CommitDeadline {
			out += "[Commit move](" + txLink("CommitMove", "matchID", id) + ")"
			if m.Ranked {
				out += " · [Bet on A](" + txLink("PlaceBet", "matchID", id, "side", "1") + ") · [Bet on B](" + txLink("PlaceBet", "matchID", id, "side", "2") + ")"
			}
			out += "\n"
		} else if height() <= m.RevealDeadline {
			out += "[Reveal](" + txLink("Reveal", "matchID", id) + ")\n"
		} else {
			out += "[Slash no-show](" + txLink("SlashNoReveal", "matchID", id) + ")\n"
		}
	}
	if len(m.Log) > 0 {
		out += "\n## Combat log\n\n| Round | A | B | HP A | HP B |\n|---|---|---|---|---|\n"
		for i, r := range m.Log {
			out += "| " + itoa(i+1) + " | " + core.MoveName(r.MoveA) + " | " + core.MoveName(r.MoveB) + " | " + itoa(r.HPA) + " | " + itoa(r.HPB) + " |\n"
		}
	}
	if m.Note != "" {
		out += "\n> " + m.Note + "\n"
	}
	return out
}

func renderFighters() string {
	out := "# 🏆 Fighters\n" + nav()
	if fighters.Size() == 0 {
		return out + "_No fighters yet._ [Register one](" + txLink("RegisterFighter") + ")\n"
	}
	out += "| # | Fighter | W / L / D | Forfeits | Trust (owner) | Backer token | Supply | Paid to backers | Source |\n|---|---|---|---|---|---|---|---|---|\n"
	badges := ""
	fighters.Iterate("", "", func(k string, v any) bool {
		f := v.(*Fighter)
		out += "| " + itoa(f.ID) + " | **" + escapeMd(f.Name) + "** | " + itoa(f.Wins) + " / " + itoa(f.Losses) + " / " + itoa(f.Draws) +
			" | " + itoa(f.Forfeits) + " | " + strconv.FormatInt(TrustScore(f.Owner), 10) +
			" | " + f.Backers.Symbol + " | " + strconv.FormatInt(f.Backers.Supply, 10) +
			" | " + strconv.FormatInt(f.Backers.Distributed, 10) + " ugnot | `" + orDash(f.PkgPath) + "` |\n"
		if len(f.Badges) > 0 {
			badges += "**" + escapeMd(f.Name) + "** "
			for _, b := range f.Badges {
				badges += badgeSVG(b) + " "
			}
			badges += "\n\n"
		}
		return false
	})
	if badges != "" {
		out += "\n## Badges\n\n" + badges
	}
	out += "\nTrust only moves on **ranked** matches with real ugnot at stake. Other realms can read it via `TrustScore(addr)`.\n"
	return out
}

func renderLab() string {
	out := "# 🧪 Breaker Lab\n" + nav()
	out += "Prompt-injection attempts, slashed no-shows and pre-flight reports. Every blocked line is a spend the AI tried that the on-chain policy refused.\n\n"
	if len(lab) == 0 {
		return out + "_No events yet._\n"
	}
	out += "| Block | Kind | Detail |\n|---|---|---|\n"
	for i := len(lab) - 1; i >= 0; i-- {
		e := lab[i]
		out += "| " + strconv.FormatInt(e.Height, 10) + " | " + kindIcon(e.Kind) + " | " + escapeMd(e.Detail) + " |\n"
	}
	return out
}

func renderExit() string {
	out := "# Emergency Exit\n\n"
	out += "This page is plain text on purpose: it works even if every external website is down.\n\n"
	out += "1. Withdraw a whole budget box: [EmergencyWithdraw](" + txLink("EmergencyWithdraw") + ") (owner only)\n"
	out += "2. Withdraw winnings, refunds, bonds and backer dividends: [Claim](" + txLink("Claim") + ")\n\n"
	out += "CLI:\n\n```\ngnokey maketx call -pkgpath " + selfPath + " -func EmergencyWithdraw -args <boxID> \\\n  -gas-fee 1000000ugnot -gas-wanted 5000000 -broadcast -chainid onyx-1 \\\n  -remote https://rpc.onyx.testnets.gno.land:443 <your-key>\n```\n\n"
	open := ""
	boxes.Iterate("", "", func(k string, v any) bool {
		b := v.(*Box)
		if !b.Closed && b.Balance > 0 {
			open += "- Box #" + itoa(b.ID) + " · owner " + string(b.Owner) + " · " + strconv.FormatInt(b.Balance, 10) +
				" ugnot · [withdraw](" + txLink("EmergencyWithdraw", "boxID", itoa(b.ID)) + ")\n"
		}
		return false
	})
	if open != "" {
		out += "Open boxes:\n\n" + open
	}
	return out
}

func yesNo(b bool) string {
	if b {
		return "✅"
	}
	return "⏳"
}

func orDash(s string) string {
	if s == "" {
		return "—"
	}
	return s
}

func kindIcon(k string) string {
	switch k {
	case "blocked":
		return "🛡️ blocked"
	case "slash":
		return "🔪 slash"
	case "preflight":
		return "🔍 preflight"
	case "exit":
		return "🚪 exit"
	}
	return k
}

func escapeMd(s string) string {
	s = strings.ReplaceAll(s, "|", "\\|")
	s = strings.ReplaceAll(s, "\n", " ")
	return s
}

// Package aegis_pit is the main Aegis Pit realm:
// an oracle-free prediction market on deterministic AI duels,
// with policy-locked budget boxes for AI agents and an always-on exit.
package aegis_pit

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	Denom              = "ugnot"
	MinBond      int64 = 1_000
	MinBet       int64 = 1
	CommitWindow int64 = 30 // blocks after both fighters are in
	RevealWindow int64 = 30 // blocks after the commit deadline
	MaxLab             = 50
)

var (
	selfPath   string          // e.g. gno.land/r/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_pit
	fighters   = avl.NewTree() // id -> *Fighter
	matches    = avl.NewTree() // id -> *Match
	boxes      = avl.NewTree() // id -> *Box
	credits    = avl.NewTree() // addr -> int64 claimable ugnot
	trust      = avl.NewTree() // owner addr -> *core.TrustRecord
	seasonFund int64
	nFighters  int
	nMatches   int
	nBoxes     int
	lab        []LabEvent
)

// LabEvent is a line in the Breaker Lab (blocked attacks, slashes, preflight reports).
type LabEvent struct {
	Height int64
	Kind   string
	Detail string
}

func init(cur realm) {
	selfPath = cur.PkgPath()
}

// ---------- helpers ----------

func height() int64 { return runtime.ChainHeight() }

func key(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 8 {
		s = "0" + s
	}
	return s
}

// takeDeposit returns the ugnot attached to a direct user call.
// Indirect calls are refused so OriginSend can't describe a phantom payment.
func takeDeposit(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("aegis: deposits must come from a direct user call (gnokey maketx call / gnoweb)")
	}
	return unsafe.OriginSend().AmountOf(Denom)
}

func caller(cur realm) address { return cur.Previous().Address() }

func send(cur realm, to address, amt int64) {
	if amt <= 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{Denom, amt}})
}

func addCredit(a address, amt int64) {
	if amt <= 0 {
		return
	}
	credits.Set(string(a), CreditOf(a)+amt)
}

func logLab(kind, detail string) {
	lab = append(lab, LabEvent{Height: height(), Kind: kind, Detail: detail})
	if len(lab) > MaxLab {
		lab = lab[len(lab)-MaxLab:]
	}
}

func linkPath() string {
	return strings.TrimPrefix(selfPath, "gno.land")
}

// txLink builds a gnoweb "$help" link that pre-fills a call form.
func txLink(fn string, kv ...string) string {
	s := linkPath() + "$help&func=" + fn
	for i := 0; i+1 < len(kv); i += 2 {
		s += "&" + kv[i] + "=" + kv[i+1]
	}
	return s
}

// ---------- credits (pull payments) ----------

// CreditOf returns claimable ugnot for an address (winnings, refunds, bonds, dividends).
func CreditOf(a address) int64 {
	v := credits.Get(string(a))
	if v == nil {
		return 0
	}
	return v.(int64)
}

// Claim withdraws all claimable ugnot to the caller.
func Claim(cur realm) int64 {
	who := caller(cur)
	amt := CreditOf(who)
	if amt <= 0 {
		panic("aegis: nothing to claim")
	}
	credits.Remove(string(who))
	send(cur, who, amt)
	return amt
}

// SeasonFund returns the season prize pool (2% of every ranked pool).
func SeasonFund() int64 { return seasonFund }

package aegis_pit

import (
	"encoding/base64"
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
)

// All visuals are generated on-chain and embedded as data-URI images,
// so gnoweb shows them with no external hosting.

const (
	cBg     = "#14110f"
	cPanel  = "#221c17"
	cGold   = "#e8b44a"
	cRed    = "#d9534f"
	cTeal   = "#3fb6a8"
	cText   = "#f3e9dc"
	cMuted  = "#9c8f80"
	svgFont = "font-family='ui-monospace,Menlo,monospace'"
)

func itoa(i int) string { return strconv.Itoa(i) }

func svgImage(alt, body string, w, h int) string {
	s := "<svg xmlns='http://www.w3.org/2000/svg' width='" + itoa(w) + "' height='" + itoa(h) +
		"' viewBox='0 0 " + itoa(w) + " " + itoa(h) + "'>" +
		"<rect width='100%' height='100%' rx='14' fill='" + cBg + "'/>" + body + "</svg>"
	return "![" + alt + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(s)) + ")"
}

func text(x, y int, size int, fill, anchor, s string) string {
	return "<text x='" + itoa(x) + "' y='" + itoa(y) + "' font-size='" + itoa(size) + "' fill='" + fill +
		"' text-anchor='" + anchor + "' " + svgFont + ">" + escape(s) + "</text>"
}

func rect(x, y, w, h int, fill string) string {
	return "<rect x='" + itoa(x) + "' y='" + itoa(y) + "' width='" + itoa(w) + "' height='" + itoa(h) +
		"' rx='4' fill='" + fill + "'/>"
}

func escape(s string) string {
	out := ""
	for _, r := range s {
		switch r {
		case '<':
			out += "&lt;"
		case '>':
			out += "&gt;"
		case '&':
			out += "&amp;"
		case '\'':
			out += "&#39;"
		default:
			out += string(r)
		}
	}
	return out
}

func hpBar(x, y, w, hp int, fill string) string {
	filled := w * hp / core.StartHP
	return rect(x, y, w, 14, cPanel) + rect(x, y, filled, 14, fill) +
		text(x+w/2, y+11, 11, cText, "middle", itoa(hp)+" HP")
}

// matchCardSVG draws the duel board: names, HP bars, pool split, phase.
func matchCardSVG(m *Match) string {
	fa := getFighter(m.A)
	nameB := "waiting…"
	if m.B != 0 {
		nameB = getFighter(m.B).Name
	}
	hpA, hpB := core.StartHP, core.StartHP
	if len(m.Log) > 0 {
		last := m.Log[len(m.Log)-1]
		hpA, hpB = last.HPA, last.HPB
	}
	if m.Status == StatusForfeit {
		if m.Winner == 1 {
			hpB = 0
		} else if m.Winner == 2 {
			hpA = 0
		} else {
			hpA, hpB = 0, 0
		}
	}
	body := text(20, 30, 13, cMuted, "start", "MATCH #"+itoa(m.ID)+" · "+modeLabel(m)+" · "+phase(m))
	body += text(20, 62, 18, cGold, "start", fa.Name)
	body += text(460, 62, 18, cTeal, "end", nameB)
	body += text(240, 62, 16, cMuted, "middle", "VS")
	body += hpBar(20, 74, 190, hpA, cGold)
	body += hpBar(270, 74, 190, hpB, cTeal)

	total := m.PoolA + m.PoolB
	wA := 220
	if total > 0 {
		wA = int(int64(440) * m.PoolA / total)
	}
	body += rect(20, 104, 440, 10, cTeal) + rect(20, 104, wA, 10, cGold)
	body += text(20, 134, 12, cText, "start", strconv.FormatInt(m.PoolA, 10)+" ugnot")
	body += text(460, 134, 12, cText, "end", strconv.FormatInt(m.PoolB, 10)+" ugnot")
	if m.Status == StatusResolved || m.Status == StatusForfeit {
		w := "DRAW"
		if m.Winner == 1 {
			w = fa.Name + " WINS"
		} else if m.Winner == 2 {
			w = nameB + " WINS"
		}
		body += text(240, 134, 13, cRed, "middle", w)
	}
	return svgImage("match "+itoa(m.ID), body, 480, 150)
}

func badgeSVG(name string) string {
	color := cGold
	switch name {
	case "Untouched":
		color = cTeal
	case "Giant Slayer":
		color = cRed
	}
	body := "<circle cx='40' cy='34' r='24' fill='" + cPanel + "' stroke='" + color + "' stroke-width='3'/>" +
		"<polygon points='40,18 45,30 58,31 48,39 51,52 40,45 29,52 32,39 22,31 35,30' fill='" + color + "'/>" +
		text(40, 78, 10, cText, "middle", name)
	return svgImage(name, body, 80, 88)
}

func modeLabel(m *Match) string {
	if m.Ranked {
		return "RANKED"
	}
	return "FRIENDLY"
}

func phase(m *Match) string {
	switch m.Status {
	case StatusLive:
		if height() <= m.CommitDeadline {
			return "COMMIT + BETS until #" + strconv.FormatInt(m.CommitDeadline, 10)
		}
		return "REVEAL until #" + strconv.FormatInt(m.RevealDeadline, 10)
	}
	return upper(m.Status)
}

func upper(s string) string {
	out := ""
	for _, r := range s {
		if r >= 'a' && r <= 'z' {
			r = r - 'a' + 'A'
		}
		out += string(r)
	}
	return out
}

// Package sample_consumer proves that other projects can reuse Aegis Pit:
//   - it imports the pure package /p/aegispit/aegis_core (policy + duel engine)
//   - it reads TrustScore from the /r/aegispit/aegis_pit realm
package sample_consumer

import (
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
	pit "gno.land/r/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_pit"
)

// MinTrust is the reputation required to enter the VIP table.
const MinTrust int64 = 520

var (
	vip      []address
	lastDuel string
)

// CheckSpend runs an arbitrary spend through an aegis_core Policy
// that only allows tipping the bartender up to 50 ugnot.
func CheckSpend(bartender, target address, fn string, amt int64) string {
	p, err := core.NewPolicy(string(bartender), "Tip", 50, 0)
	if err != nil {
		return "policy error: " + err.Error()
	}
	if err := core.ValidateSpend(p, target, fn, amt, 0); err != nil {
		return "DENIED: " + err.Error()
	}
	return "OK"
}

// PracticeDuel uses the same deterministic engine as the arena.
func PracticeDuel(cur realm, movesA, movesB string) int {
	if err := core.ValidateMoves(movesA); err != nil {
		panic(err.Error())
	}
	if err := core.ValidateMoves(movesB); err != nil {
		panic(err.Error())
	}
	w, _ := core.ResolveDuel(movesA, movesB)
	lastDuel = movesA + " vs " + movesB + " → winner " + strconv.Itoa(w)
	return w
}

// EnterVIP gates access on the caller's Aegis Pit trust score.
func EnterVIP(cur realm) {
	who := cur.Previous().Address()
	score := pit.TrustScore(who)
	if score < MinTrust {
		panic("trust " + strconv.FormatInt(score, 10) + " < " + strconv.FormatInt(MinTrust, 10) + ": win a ranked match in Aegis Pit first")
	}
	vip = append(vip, who)
}

func Render(path string) string {
	out := "# 🍺 Sample Consumer — The VIP Table\n\n"
	out += "This realm imports `gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core` and reads `TrustScore` from `gno.land/r/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_pit`.\n\n"
	out += "- VIP entry needs trust ≥ " + strconv.FormatInt(MinTrust, 10) + "\n"
	out += "- VIP guests: " + strconv.Itoa(len(vip)) + "\n"
	if lastDuel != "" {
		out += "- Last practice duel: " + lastDuel + "\n"
	}
	return out
}

