package urim

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"gno.land/p/g1efejv30mcyz2tglm36263ha83ttv4zfu0gnnq0/hat/v0"
)

// Message returns the exact bytes a participant signs for a call:
//
//	urim/v1 \n <draw id> \n <phase> \n <hex sha256(payload)> \n <nonce>
//
// where payload is the action name and the call's fields joined by "\n".
// Phones build the same bytes in web/lib/protocol.ts.
func Message(id int64, phase hat.Phase, nonce int64, fields ...string) []byte {
	sum := sha256.Sum256([]byte(strings.Join(fields, "\n")))
	return []byte("urim/v1\n" + strconv.FormatInt(id, 10) + "\n" + phase.String() + "\n" +
		hex.EncodeToString(sum[:]) + "\n" + strconv.FormatInt(nonce, 10))
}

// verifySig panics unless sig (hex) is pub's Ed25519 signature of the
// message for these fields. Verification happens here, in the realm.
func verifySig(pub []byte, id int64, phase hat.Phase, nonce int64, sig string, fields ...string) {
	s := mustHex("sig", sig, 64)
	if !ed25519.Verify(pub, Message(id, phase, nonce, fields...), s) {
		panic("urim: bad signature")
	}
}

func mustHex(what, s string, size int) []byte {
	if len(s) != 2*size || strings.ToLower(s) != s {
		panic("urim: " + what + " must be " + strconv.Itoa(size) + " bytes of lowercase hex")
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		panic("urim: " + what + " is not hex")
	}
	return b
}

func mustB64(what, s string) []byte {
	if len(s) > base64.StdEncoding.EncodedLen(hat.MaxBlob) {
		panic("urim: " + what + " is too large")
	}
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic("urim: " + what + " is not base64")
	}
	// Exactly one encoding per blob, so a signed string means one thing.
	if base64.StdEncoding.EncodeToString(b) != s {
		panic("urim: " + what + " is not canonical base64")
	}
	return b
}

func splitB64(items string, n int) [][]byte {
	parts := strings.Split(items, ",")
	if len(parts) > n+1 {
		// Room for one extra so the hat can report "slip count changed";
		// anything larger is not worth decoding.
		panic("urim: too many items")
	}
	out := make([][]byte, len(parts))
	for k, p := range parts {
		out[k] = mustB64("item", p)
	}
	return out
}

// checkText rejects text that is too long, not UTF-8, or has control
// characters or markup brackets. Render escapes the rest.
func checkText(what, s string, min, max int) {
	if len(s) < min || len(s) > max {
		panic("urim: " + what + " must be " + strconv.Itoa(min) + " to " + strconv.Itoa(max) + " bytes")
	}
	if !utf8.ValidString(s) {
		panic("urim: " + what + " is not UTF-8")
	}
	for _, r := range s {
		if unicode.IsControl(r) || r == '<' || r == '>' || r == '\\' || r == '"' {
			panic("urim: " + what + " has a character that is not allowed")
		}
	}
	if strings.TrimSpace(s) != s {
		panic("urim: " + what + " has leading or trailing spaces")
	}
}

// checkName allows letters, digits, spaces and . - ' only.
func checkName(name string) {
	checkText("name", name, 1, 40)
	for _, r := range name {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != ' ' && r != '.' && r != '-' && r != '\'' {
			panic("urim: names may use letters, digits, spaces and . - ' only")
		}
	}
}

func sameName(a, b string) bool { return strings.EqualFold(a, b) }

func bytesEq(a, b []byte) bool { return string(a) == string(b) }

func sha256Sum(b []byte) []byte {
	s := sha256.Sum256(b)
	return s[:]
}

package urim

// Deploy-time settings. scripts/set-namespace.sh rewrites both before an
// addpkg to a real network, so the realm links to the right web app.
const (
	// AppOrigin is the web app the gnoweb buttons open.
	AppOrigin = "https://urim-mu.vercel.app"
	// realmLink is this realm's gnoweb path.
	realmLink = "/r/g1efejv30mcyz2tglm36263ha83ttv4zfu0gnnq0/urim/v0"
)

package urim

import (
	"strconv"
	"strings"

	"gno.land/p/g1efejv30mcyz2tglm36263ha83ttv4zfu0gnnq0/hat/v0"
)

// Render shows public state only: names, phase, turns done, slot
// fingerprints, counts and checks. Never a pairing; the realm does not know one.
//
//	Render("")     open draws and the public counter
//	Render("<id>") one draw (gnoweb: /r/.../urim:<id>)
func Render(path string) string {
	path = strings.TrimPrefix(path, ":")
	if path == "" {
		return renderHome()
	}
	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil || draws.Get(key(id)) == nil {
		return "# Draw not found\n\nThere is no Urim draw with that number. [See open draws](" + realmLink + ")\n"
	}
	return renderDraw(mustDraw(id))
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Urim: Secret Santa nobody can peek at\n\n")
	b.WriteString("Draw Secret Santa names online so nobody, not even the organiser, can peek or rig who gets whom.\n\n")
	b.WriteString("<gno-button href=\"" + AppOrigin + "\" label=\"Start a draw on your phone\" />\n\n")
	b.WriteString("## Open draws\n\n")
	shown := 0
	draws.ReverseIterate("", "", func(_ string, v any) bool {
		d := v.(*draw)
		if d.hat.Phase().Terminal() {
			return false
		}
		b.WriteString("- [" + esc(d.title) + "](" + realmLink + ":" + strconv.FormatInt(d.id, 10) + ") · " +
			plural(len(d.people), "person", "people") + " · " + phaseWords(d.hat) + "\n")
		shown++
		return shown >= 20
	})
	if shown == 0 {
		b.WriteString("No open draws right now.\n")
	}
	b.WriteString("\n## Counter\n\n")
	b.WriteString("| Draws completed | People | Voided |\n|---|---|---|\n")
	b.WriteString("| " + strconv.Itoa(completed) + " | " + strconv.Itoa(people) + " | " + strconv.Itoa(voided) + " |\n")
	return b.String()
}

func renderDraw(d *draw) string {
	h := d.hat
	ph := h.Phase()
	id := strconv.FormatInt(d.id, 10)
	var b strings.Builder

	// A leading h1 and a long-enough first paragraph become the page's
	// <title> and description in gnoweb, so shared links preview well.
	b.WriteString("# Urim: Secret Santa for " + esc(d.title) + "\n\n")
	b.WriteString(plural(len(d.people), "person has", "people have") + " joined. " +
		"Nobody can peek: every phone signs its own moves and a tampered hat cancels the draw.\n\n")

	app := AppOrigin + "/d/" + id
	if ph == hat.Join {
		b.WriteString("<gno-button href=\"" + app + "?join=1\" label=\"Join on your phone\" /> ")
	}
	b.WriteString("<gno-button href=\"" + app + "\" label=\"View in app\" variant=\"outline\" />\n\n")

	b.WriteString("| | |\n|---|---|\n")
	if d.budget != "" {
		b.WriteString("| Budget | " + esc(d.budget) + " |\n")
	}
	if d.date != "" {
		b.WriteString("| Exchange | " + esc(d.date) + " |\n")
	}
	mode := "async (a day per step)"
	if d.live {
		mode = "live (10 minutes per step)"
	}
	b.WriteString("| Mode | " + mode + " |\n")
	b.WriteString("| Phase | " + ph.String() + ": " + phaseWords(h) + " |\n")
	if !ph.Terminal() {
		b.WriteString("| Deadline | " + h.Deadline().UTC().Format("2006-01-02 15:04 UTC") + " (block time) |\n")
	}
	if ph == hat.Voided {
		b.WriteString("| Why | " + esc(h.Reason()) + " |\n")
		if d.next != 0 {
			n := strconv.FormatInt(d.next, 10)
			b.WriteString("| Fresh draw | [#" + n + "](" + realmLink + ":" + n + ") |\n")
		}
	}
	b.WriteString("\n")

	b.WriteString("## People\n\n")
	shufflerTurn := map[int]int{}
	for t, s := range h.Shufflers() {
		shufflerTurn[s] = t + 1
	}
	for i, p := range d.people {
		line := strconv.Itoa(i+1) + ". " + esc(p.name)
		if bytesEq(p.signPub, d.organiser) {
			line += " (organiser)"
		}
		if t, ok := shufflerTurn[i]; ok {
			line += " · shuffler " + strconv.Itoa(t)
		}
		if h.Done(i) && (ph == hat.Locked || ph == hat.Seal1 || ph == hat.Seal2) {
			line += " · ✓"
		}
		b.WriteString(line + "\n")
	}
	b.WriteString("\n")

	if ph >= hat.Seal1 && ph != hat.Voided {
		b.WriteString("## Shuffle turns\n\n")
		for round := 1; round <= 2; round++ {
			b.WriteString("- Round " + strconv.Itoa(round) + ": " + turnTicks(h, round) + "\n")
		}
		b.WriteString("\n")
	}

	if slots := h.Slots(); len(slots) > 0 {
		b.WriteString("## Slots in the circle\n\n")
		b.WriteString("Each slot gives to the next one, wrapping round. Nobody but its owner knows whose slot is whose.\n\n")
		fps := make([]string, len(slots))
		for k, s := range slots {
			fps[k] = "`" + hat.Fingerprint(s) + "`"
		}
		b.WriteString(strings.Join(fps, " → ") + " → back to the start\n\n")
	}

	b.WriteString("## Checks\n\n")
	n := len(d.people)
	switch {
	case ph == hat.Check:
		b.WriteString("- Phones that found their own slot: " + strconv.Itoa(h.Count()) + "/" + strconv.Itoa(n) + "\n")
	case ph > hat.Check && ph != hat.Voided:
		b.WriteString("- Every phone found its own slot: ✓\n")
	}
	if ph == hat.Revealed {
		b.WriteString("- One slip for every slot: ✓\n")
		b.WriteString("- Phones that opened a genuine slip: " + strconv.Itoa(h.Count()) + "/" + strconv.Itoa(n) + "\n")
	}
	if ph < hat.Check {
		b.WriteString("- Checks start after the first shuffle.\n")
	}
	if ph == hat.Voided {
		b.WriteString("- The draw was called off for everyone. No pairing was revealed.\n")
	}
	return b.String()
}

func turnTicks(h *hat.Hat, round int) string {
	total := len(h.Shufflers())
	done := 0
	ph := h.Phase()
	cur := hat.Mix1
	if round == 2 {
		cur = hat.Mix2
	}
	switch {
	case ph == cur:
		done = h.Turn()
	case ph > cur && ph != hat.Voided:
		done = total
	}
	ticks := make([]string, total)
	for t := range ticks {
		ticks[t] = "·"
		if t < done {
			ticks[t] = "✓"
		}
	}
	return strings.Join(ticks, " ") + " (" + strconv.Itoa(done) + "/" + strconv.Itoa(total) + ")"
}

func phaseWords(h *hat.Hat) string {
	switch h.Phase() {
	case hat.Join:
		return "open for joining"
	case hat.Locked:
		return "checking in, " + strconv.Itoa(h.Count()) + "/" + strconv.Itoa(h.Size()) + " phones ready"
	case hat.Seal1:
		return "making tickets, " + strconv.Itoa(h.Count()) + "/" + strconv.Itoa(h.Size())
	case hat.Mix1:
		return "shuffling, turn " + strconv.Itoa(h.Turn()+1) + " of " + strconv.Itoa(len(h.Shufflers()))
	case hat.Check:
		return "checking tickets"
	case hat.Seal2:
		return "folding names, " + strconv.Itoa(h.Count()) + "/" + strconv.Itoa(h.Size())
	case hat.Mix2:
		return "shuffling again, turn " + strconv.Itoa(h.Turn()+1) + " of " + strconv.Itoa(len(h.Shufflers()))
	case hat.Revealed:
		if h.Completed() {
			return "everyone has their name"
		}
		return "names revealed on each phone"
	}
	return "called off"
}

func plural(n int, one, many string) string {
	if n == 1 {
		return "1 " + one
	}
	return strconv.Itoa(n) + " " + many
}

// esc makes user text inert in gnoweb markdown.
func esc(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '#', '+', '-', '.', '!', '|', '~', '&', '@', ':':
			b.WriteRune('\\')
		}
		b.WriteRune(r)
	}
	return b.String()
}

package urim

import (
	"encoding/base64"
	"encoding/hex"
	"strconv"
	"strings"
)

// State returns one draw's public state as JSON, for phones to read with a
// vm/qeval query. It holds exactly what the chain already shows; nothing in
// it links a slot or slip to a person.
func State(id int64) string {
	v := draws.Get(key(id))
	if v == nil {
		return "null"
	}
	d := v.(*draw)
	h := d.hat
	var b strings.Builder
	b.WriteString("{")
	field(&b, "id", strconv.FormatInt(d.id, 10))
	field(&b, "title", strconv.Quote(d.title))
	field(&b, "budget", strconv.Quote(d.budget))
	field(&b, "date", strconv.Quote(d.date))
	field(&b, "live", strconv.FormatBool(d.live))
	field(&b, "organiser", strconv.Quote(hex.EncodeToString(d.organiser)))
	field(&b, "phase", strconv.Quote(h.Phase().String()))
	field(&b, "deadline", strconv.FormatInt(h.Deadline().Unix(), 10))
	field(&b, "turn", strconv.Itoa(h.Turn()))
	field(&b, "expected", strconv.Itoa(h.Expected()))
	field(&b, "count", strconv.Itoa(h.Count()))
	field(&b, "completed", strconv.FormatBool(h.Completed()))
	field(&b, "reason", strconv.Quote(h.Reason()))
	field(&b, "next", strconv.FormatInt(d.next, 10))
	field(&b, "seed", strconv.Quote(hex.EncodeToString(h.Seed())))

	people := make([]string, len(d.people))
	for i, p := range d.people {
		people[i] = "{\"name\":" + strconv.Quote(p.name) +
			",\"sign\":\"" + hex.EncodeToString(p.signPub) +
			"\",\"box\":\"" + hex.EncodeToString(p.boxPub) +
			"\",\"done\":" + strconv.FormatBool(h.Done(i)) + "}"
	}
	field(&b, "people", "["+strings.Join(people, ",")+"]")

	sh := make([]string, len(h.Shufflers()))
	for t, s := range h.Shufflers() {
		sh[t] = strconv.Itoa(s)
	}
	field(&b, "shufflers", "["+strings.Join(sh, ",")+"]")
	field(&b, "contents", list(h.Contents(), base64.StdEncoding.EncodeToString))
	field(&b, "slots", list(h.Slots(), hex.EncodeToString))
	b.WriteString("\"slips\":" + list(h.Slips(), base64.StdEncoding.EncodeToString) + "}")
	return b.String()
}

// Stats returns the public counter as JSON.
func Stats() string {
	return "{\"completed\":" + strconv.Itoa(completed) + ",\"people\":" + strconv.Itoa(people) +
		",\"voided\":" + strconv.Itoa(voided) + ",\"draws\":" + strconv.FormatInt(lastID, 10) + "}"
}

func field(b *strings.Builder, name, value string) {
	b.WriteString("\"" + name + "\":" + value + ",")
}

func list(items [][]byte, enc func([]byte) string) string {
	out := make([]string, len(items))
	for k, it := range items {
		out[k] = "\"" + enc(it) + "\""
	}
	return "[" + strings.Join(out, ",") + "]"
}

// Package urim draws Secret Santa names so nobody, not even the organiser,
// can peek or rig who gets whom.
//
// The realm stores each draw, checks every caller's Ed25519 signature
// itself, rejects replays, and drives a p/hat state machine. It never learns
// who gives to whom: see docs/PROTOCOL.md.
//
// Every state-changing function is signed by a participant's own key, so it
// can be submitted by anyone (a relay that pays gas, or the participant's own
// wallet) without giving the submitter any power.
package urim

import (
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1efejv30mcyz2tglm36263ha83ttv4zfu0gnnq0/hat/v0"
)

const (
	liveStep   = 10 * time.Minute // per phase and per shuffle turn, live draws
	asyncStep  = 24 * time.Hour   // same, for draws run over a few days
	joinWindow = 14 * 24 * time.Hour

	slipSize = hat.KeySize + 208 // slot key + sealed slip (see PROTOCOL.md step 6)

	reasonSlot = "my slot is missing"
	reasonSlip = "my slip is missing or duplicated"
)

type person struct {
	name    string
	signPub []byte
	boxPub  []byte
	nonce   int64
}

type draw struct {
	id        int64
	title     string
	budget    string
	date      string
	live      bool
	organiser []byte
	orgNonce  int64 // used only while the organiser has not joined
	people    []*person
	hat       *hat.Hat
	created   time.Time
	next      int64 // a fresh draw started from this voided one
	settled   bool  // already counted in the public counter
}

var (
	draws      avl.Tree // key(id) -> *draw
	organisers avl.Tree // hex organiser key -> true; one draw per key, so Create cannot be replayed
	lastID     int64

	// The public counter.
	completed int
	people    int
	voided    int
)

func key(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func mustDraw(id int64) *draw {
	v := draws.Get(key(id))
	if v == nil {
		panic("urim: no such draw")
	}
	return v.(*draw)
}

// Create opens a new draw and returns its id. The organiser is whoever holds
// the key orgPub; that key alone may later lock the roster.
// mode is "live" (everyone together, minutes per step) or "async" (a day per step).
func Create(_ realm, title, budget, date, mode, orgPub string, nonce int64, sig string) int64 {
	checkText("title", title, 1, 60)
	checkText("budget", budget, 0, 40)
	checkText("date", date, 0, 24)
	if mode != "live" && mode != "async" {
		panic("urim: mode must be live or async")
	}
	pub := mustHex("orgPub", orgPub, 32)
	if organisers.Has(orgPub) {
		panic("urim: this key already created a draw")
	}
	verifySig(pub, 0, hat.Join, nonce, sig, "create", title, budget, date, mode, orgPub)
	organisers.Set(orgPub, true)

	now := time.Now()
	step := asyncStep
	if mode == "live" {
		step = liveStep
	}
	lastID++
	d := &draw{
		id: lastID, title: title, budget: budget, date: date, live: mode == "live",
		organiser: pub, orgNonce: nonce, created: now,
		hat: hat.New(hat.Options{Rounds: 2, Slip: slipSize, Step: step, JoinWindow: joinWindow}, now),
	}
	draws.Set(key(d.id), d)
	return d.id
}

// Join adds the signer to the roster with a name, its signing and box public
// keys, and commit = sha256(seed) for the seed it will reveal after Lock.
func Join(_ realm, id int64, name, signPub, boxPub, commit string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.expire() {
		return
	}
	checkName(name)
	for _, p := range d.people {
		if sameName(p.name, name) {
			panic("urim: that name is taken in this draw")
		}
	}
	pub := mustHex("signPub", signPub, 32)
	if d.find(pub) >= 0 {
		panic("urim: already joined")
	}
	box := mustHex("boxPub", boxPub, 32)
	c := mustHex("commit", commit, 32)
	// The nonce sequence of a key that already signed (the organiser's) carries on.
	last := int64(0)
	if bytesEq(pub, d.organiser) {
		last = d.orgNonce
	}
	if nonce <= last {
		panic("urim: replayed or stale nonce")
	}
	verifySig(pub, d.id, hat.Join, nonce, sig, "join", name, signPub, boxPub, commit)
	if _, err := d.hat.Add(box, c, time.Now()); err != nil {
		panic(err.Error())
	}
	d.people = append(d.people, &person{name: name, signPub: pub, boxPub: box, nonce: nonce})
}

// Lock freezes the roster. Only the organiser's key may sign it.
func Lock(_ realm, id int64, signPub string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.expire() {
		return
	}
	pub := mustHex("signPub", signPub, 32)
	if !bytesEq(pub, d.organiser) {
		panic("urim: only the organiser can lock the roster")
	}
	d.auth(pub, nonce, sig, "lock")
	if err := d.hat.Lock(d.find(pub), time.Now()); err != nil {
		panic(err.Error())
	}
}

// Ready reveals the signer's seed. When the last one is in, the realm fixes
// the draw seed and picks the shufflers from it.
func Ready(_ realm, id int64, signPub, seed string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.expire() {
		return
	}
	i := d.member(signPub)
	s := mustHex("seed", seed, 32)
	d.auth(d.people[i].signPub, nonce, sig, "ready", seed)
	if err := d.hat.Ready(i, s, d.roster(), time.Now()); err != nil {
		panic(err.Error())
	}
}

// Seal posts the signer's onion for the current seal phase (Seal1 or Seal2).
func Seal(_ realm, id int64, signPub, onion string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.expire() {
		return
	}
	i := d.member(signPub)
	b := mustB64("onion", onion)
	d.auth(d.people[i].signPub, nonce, sig, "seal", onion)
	if err := d.hat.Seal(i, b, time.Now()); err != nil {
		panic(err.Error())
	}
}

// Mix posts one shuffle turn: the hat's contents with one layer peeled and
// shuffled, as comma-separated base64. Only the expected shuffler may sign
// it. Output that shows tampering voids the draw instead of being rejected.
func Mix(_ realm, id int64, signPub, items string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.expire() {
		return
	}
	i := d.member(signPub)
	out := splitB64(items, d.hat.Size())
	d.auth(d.people[i].signPub, nonce, sig, "mix", items)
	if err := d.hat.Mix(i, out, time.Now()); err != nil {
		panic(err.Error())
	}
	d.settle()
}

// Confirm says the signer's phone found its own slot (in Check) or opened a
// genuine slip (in Revealed).
func Confirm(_ realm, id int64, signPub string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.expire() {
		return
	}
	i := d.member(signPub)
	d.auth(d.people[i].signPub, nonce, sig, "confirm")
	if err := d.hat.Confirm(i, time.Now()); err != nil {
		panic(err.Error())
	}
	d.settle()
}

// Void calls the draw off for everyone, on the signer's claim that its slot
// is missing (in Check) or its slip is missing, duplicated or forged (after
// Mix2). The claim cannot reveal a pairing; it only cancels.
func Void(_ realm, id int64, signPub, reason string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.expire() {
		return
	}
	switch {
	case d.hat.Phase() == hat.Check && reason == reasonSlot:
	case d.hat.Phase() == hat.Revealed && reason == reasonSlip:
	default:
		panic("urim: Void takes \"" + reasonSlot + "\" in Check or \"" + reasonSlip + "\" after the reveal")
	}
	i := d.member(signPub)
	d.auth(d.people[i].signPub, nonce, sig, "void", reason)
	if err := d.hat.Void(i, d.people[i].name+": "+reason, time.Now()); err != nil {
		panic(err.Error())
	}
	d.settle()
}

// Expire voids a draw whose current phase or turn has run out of block time.
// Anyone may call it; it does nothing before the deadline.
func Expire(_ realm, id int64) {
	if !mustDraw(id).expire() {
		panic("urim: deadline has not passed")
	}
}

// Relink points a voided draw at the fresh draw that replaces it, so every
// phone that was in the old one can find the new one. Any participant of the
// old draw may sign it, once.
func Relink(_ realm, id, next int64, signPub string, nonce int64, sig string) {
	d := mustDraw(id)
	if d.hat.Phase() != hat.Voided {
		panic("urim: only a voided draw can be restarted")
	}
	if d.next != 0 {
		panic("urim: already restarted")
	}
	n := mustDraw(next)
	if n.created.Before(d.created) || n.hat.Phase() != hat.Join {
		panic("urim: the fresh draw must be newer and still open")
	}
	i := d.member(signPub)
	d.auth(d.people[i].signPub, nonce, sig, "relink", strconv.FormatInt(next, 10))
	d.next = next
}

// expire voids d if its deadline has passed and reports whether it did.
// Calls that arrive late commit the void instead of failing, so the draw
// never sits stuck in a phase nobody can finish.
func (d *draw) expire() bool {
	if !d.hat.Expire(time.Now()) {
		return false
	}
	d.settle()
	return true
}

// settle updates the public counter once a draw is completed or voided.
func (d *draw) settle() {
	if d.settled {
		return
	}
	switch {
	case d.hat.Phase() == hat.Voided:
		voided++
	case d.hat.Completed():
		completed++
		people += len(d.people)
	default:
		return
	}
	d.settled = true
}

func (d *draw) find(pub []byte) int {
	for i, p := range d.people {
		if bytesEq(p.signPub, pub) {
			return i
		}
	}
	return -1
}

// member returns the roster index of the hex signing key, or panics.
func (d *draw) member(signPub string) int {
	i := d.find(mustHex("signPub", signPub, 32))
	if i < 0 {
		panic("urim: not in this draw")
	}
	return i
}

// auth checks the signature and nonce of a call by pub on d, in the current
// phase, and records the nonce.
func (d *draw) auth(pub []byte, nonce int64, sig string, fields ...string) {
	ref := &d.orgNonce
	if i := d.find(pub); i >= 0 {
		ref = &d.people[i].nonce
	}
	if nonce <= *ref {
		panic("urim: replayed or stale nonce")
	}
	verifySig(pub, d.id, d.hat.Phase(), nonce, sig, fields...)
	*ref = nonce
}

// roster digests the names and signing keys, which the hat does not see,
// so the draw seed is bound to them too.
func (d *draw) roster() []byte {
	var buf []byte
	for _, p := range d.people {
		buf = append(buf, []byte(p.name)...)
		buf = append(buf, 0)
		buf = append(buf, p.signPub...)
	}
	return sha256Sum(buf)
}

// Package rolecall deals secret Werewolf / Mafia roles with p/hat: one
// werewolf, one seer, everyone else a villager. Each phone gets an anonymous
// slot through one shuffle round, and roles go to circle positions, so a
// player knows their own role and nobody knows anyone else's. Players call
// with their own wallets, so the caller's address is their identity.
package rolecall

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1efejv30mcyz2tglm36263ha83ttv4zfu0gnnq0/hat/v0"
)

type game struct {
	host    address
	players []address
	hat     *hat.Hat
}

var games avl.Tree // id -> *game

// New opens a game; the caller hosts it and alone can lock it.
func New(cur realm) int {
	id := games.Size() + 1
	h := hat.New(hat.Options{Rounds: 1, Step: 10 * time.Minute, JoinWindow: 24 * time.Hour}, time.Now())
	games.Set(strconv.Itoa(id), &game{host: cur.Previous().Address(), hat: h})
	return id
}

func Join(cur realm, id int, boxPub, commit string) {
	g := get(id)
	if g.seat(cur) >= 0 {
		panic("rolecall: already joined")
	}
	_, err := g.hat.Add(unhex(boxPub), unhex(commit), time.Now())
	check(err)
	g.players = append(g.players, cur.Previous().Address())
}

func Lock(cur realm, id int) {
	g := get(id)
	if cur.Previous().Address() != g.host {
		panic("rolecall: only the host can lock")
	}
	check(g.hat.Lock(-1, time.Now()))
}

func Ready(cur realm, id int, seed string) {
	g := get(id)
	var roster []byte
	for _, p := range g.players {
		roster = append(roster, []byte(p.String())...)
	}
	sum := sha256.Sum256(roster)
	check(g.hat.Ready(g.must(cur), unhex(seed), sum[:], time.Now()))
}

func Seal(cur realm, id int, onion string) {
	g := get(id)
	check(g.hat.Seal(g.must(cur), unb64(onion), time.Now()))
}

// Mix takes one shuffle turn: comma-separated base64, one layer peeled.
func Mix(cur realm, id int, items string) {
	g := get(id)
	var out [][]byte
	for _, s := range strings.Split(items, ",") {
		out = append(out, unb64(s))
	}
	check(g.hat.Mix(g.must(cur), out, time.Now()))
}

// Next returns who must shuffle now, or "" when nobody is.
func Next(id int) address {
	g := get(id)
	if e := g.hat.Expected(); e >= 0 {
		return g.players[e]
	}
	return ""
}

// Confirm says the caller's phone found its slot; when all have, roles are dealt.
func Confirm(cur realm, id int) {
	g := get(id)
	check(g.hat.Confirm(g.must(cur), time.Now()))
}

// Role is the role at circle position k. The circle order comes from the draw
// seed, so neither the host nor the last shuffler chooses who is the werewolf.
func Role(k int) string {
	switch k {
	case 0:
		return "werewolf"
	case 1:
		return "seer"
	}
	return "villager"
}

func Render(path string) string {
	id, _ := strconv.Atoi(strings.TrimPrefix(path, ":"))
	v := games.Get(strconv.Itoa(id))
	if v == nil {
		return "# Rolecall\n\nSecret Werewolf roles dealt with the Urim hat (p/hat): nobody, not even the host, knows who is who.\n"
	}
	h := v.(*game).hat
	out := "# Rolecall game " + strconv.Itoa(id) + "\n\n" + strconv.Itoa(h.Size()) + " players · " + h.Phase().String() + "\n\n"
	if h.Phase() == hat.Revealed {
		out += "Find your slot fingerprint on your phone:\n\n"
		for k, s := range h.Slots() {
			out += "- `" + hat.Fingerprint(s) + "` " + Role(k) + "\n"
		}
	}
	return out
}

func get(id int) *game {
	v := games.Get(strconv.Itoa(id))
	if v == nil {
		panic("rolecall: no such game")
	}
	return v.(*game)
}

func (g *game) seat(cur realm) int {
	for i, p := range g.players {
		if p == cur.Previous().Address() {
			return i
		}
	}
	return -1
}

func (g *game) must(cur realm) int {
	if i := g.seat(cur); i >= 0 {
		return i
	}
	panic("rolecall: not in this game")
}

func unhex(s string) []byte {
	b, err := hex.DecodeString(s)
	check(err)
	return b
}

func unb64(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	check(err)
	return b
}

func check(err error) {
	if err != nil {
		panic(err.Error())
	}
}

// Package lobby owns run IDs, invitations, and player assignments.
package lobby

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

type run struct {
	playerA  address
	playerB  address
	accepted bool
}

var (
	lastRunID int64
	runs      avl.Tree
)

// CreateRun invites a second wallet and returns the new run ID.
func CreateRun(cur realm, invited address) int64 {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("Connect a wallet and call the Lobby directly.")
	}
	player := cur.Previous().Address()
	if !invited.IsValid() || invited == player {
		panic("Invite a valid wallet different from your own.")
	}

	lastRunID++
	runs.Set(strconv.FormatInt(lastRunID, 10), run{playerA: player, playerB: invited})
	return lastRunID
}

// AcceptRun activates a pending run for its invited wallet.
func AcceptRun(cur realm, runID int64) {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("Connect a wallet and call the Lobby directly.")
	}
	key := strconv.FormatInt(runID, 10)
	entry, exists := runs.Get(key).(run)
	if !exists {
		panic("Run does not exist.")
	}
	if cur.Previous().Address() != entry.playerB {
		panic("Only the invited wallet can accept this run.")
	}
	if entry.accepted {
		return
	}

	entry.accepted = true
	runs.Set(key, entry)
}

// GetRun reports a run's two players and invitation status.
func GetRun(runID int64) (playerA address, playerB address, accepted bool, exists bool) {
	entry, exists := runs.Get(strconv.FormatInt(runID, 10)).(run)
	return entry.playerA, entry.playerB, entry.accepted, exists
}

// Render shows the Lobby or one run when path is its canonical decimal ID.
func Render(path string) string {
	page := "# Relay Worlds Lobby\n\n"
	base := strings.TrimPrefix(packagePath, "gno.land")
	if path == "" {
		page += "[Invite a second player](" + base + "$help&func=CreateRun)\n\n"
		if lastRunID == 0 {
			return page + "No runs have been created.\n"
		}
		page += "## Recent runs\n\n"
		for id := lastRunID; id > 0 && lastRunID-id < 10; id-- {
			key := strconv.FormatInt(id, 10)
			page += "- [Run " + key + "](" + base + ":" + key + ")\n"
		}
		return page
	}

	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil || id <= 0 || strconv.FormatInt(id, 10) != path {
		return page + "Run does not exist.\n"
	}
	playerA, playerB, accepted, exists := GetRun(id)
	if !exists {
		return page + "Run does not exist.\n"
	}

	page += "## Run " + path + "\n\nPlayer A · " + playerA.String() +
		"\n\nPlayer B · " + playerB.String() + "\n\n"
	if accepted {
		return page + "**Invitation accepted.** Player A can solve the Signal Room for run " + path + ".\n"
	}
	return page + "**Awaiting acceptance.** Share this page with Player B.\n\n" +
		"[Accept invitation](" + base + "$help&func=AcceptRun&runID=" + path + ")\n"
}

// Package signal_room owns the published clue and Signal Room completions.
package signal_room

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1vkjcgep877a4gwchg34qfprsjpg2msjmhysh0z/relay_worlds/lobby/v1"
)

type puzzle struct {
	sequence    string
	legend      string
	switchOrder string
	answer      string
}

var (
	published   puzzle
	completions avl.Tree
)

// PublishPuzzle publishes the room's one clue as the wallet owning its namespace.
func PublishPuzzle(cur realm, sequence string, legend string, switchOrder string) {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("Connect a wallet and call the Signal Room directly.")
	}
	prefix := "gno.land/r/" + cur.Previous().Address().String() + "/"
	if !strings.HasPrefix(cur.PkgPath(), prefix) {
		panic("Only the namespace owner can publish the puzzle.")
	}
	if published.answer != "" {
		panic("The puzzle has already been published.")
	}
	published = parsePuzzle(sequence, legend, switchOrder)
}

// Solve records a correct answer from Player A for an accepted run.
func Solve(cur realm, runID int64, answer string) {
	if !cur.IsCurrent() || !cur.Previous().IsUserCall() {
		panic("Connect a wallet and call the Signal Room directly.")
	}
	playerA, _, accepted, exists := lobby.GetRun(runID)
	if !exists {
		panic("Run does not exist.")
	}
	if !accepted {
		panic("Player B must accept the invitation first.")
	}
	if cur.Previous().Address() != playerA {
		panic("Only Player A can solve the Signal Room.")
	}
	if published.answer == "" {
		panic("The Signal Room puzzle is unavailable.")
	}
	if strings.ToUpper(strings.TrimSpace(answer)) != published.answer {
		panic("That code is incorrect.")
	}
	if IsComplete(runID) {
		return
	}

	completions.Set(strconv.FormatInt(runID, 10), true)
}

// IsComplete reports whether a run has a recorded Signal Room solve.
func IsComplete(runID int64) bool {
	return completions.Has(strconv.FormatInt(runID, 10))
}

func parsePuzzle(sequence string, legend string, switchOrder string) puzzle {
	colors := strings.Fields(sequence)
	entries := strings.Fields(legend)
	switches := strings.Fields(switchOrder)
	if len(colors) == 0 || len(entries) == 0 || len(switches) == 0 {
		panic("Supply a color sequence, a legend, and a switch order.")
	}

	letters := make(map[string]string)
	for _, entry := range entries {
		parts := strings.SplitN(entry, "=", 2)
		if len(parts) != 2 || !isColorName(parts[0]) ||
			len(parts[1]) != 1 || parts[1][0] < 'A' || parts[1][0] > 'Z' {
			panic("Use lowercase color names and one uppercase letter per legend entry.")
		}
		if _, exists := letters[parts[0]]; exists {
			panic("Each color may appear only once in the legend.")
		}
		letters[parts[0]] = parts[1]
	}

	var answer strings.Builder
	for _, color := range colors {
		letter, exists := letters[color]
		if !exists {
			panic("Every color in the sequence needs a legend entry.")
		}
		answer.WriteString(letter)
	}

	seen := make(map[int64]bool)
	for _, position := range switches {
		number, err := strconv.ParseInt(position, 10, 64)
		if err != nil || number < 1 || number > int64(len(switches)) ||
			strconv.FormatInt(number, 10) != position || seen[number] {
			panic("The switch order must list each switch number once, starting from 1.")
		}
		seen[number] = true
	}

	return puzzle{
		sequence:    strings.Join(colors, " "),
		legend:      strings.Join(entries, " "),
		switchOrder: strings.Join(switches, " "),
		answer:      answer.String(),
	}
}

func isColorName(name string) bool {
	if name == "" {
		return false
	}
	for _, letter := range name {
		if letter < 'a' || letter > 'z' {
			return false
		}
	}
	return true
}

// Render shows the clue and the next action for a run's canonical decimal ID.
func Render(path string) string {
	page := "# Signal Room\n\n"
	base := strings.TrimPrefix(packagePath, "gno.land")
	lobbyBase := strings.TrimPrefix("gno.land/r/g1vkjcgep877a4gwchg34qfprsjpg2msjmhysh0z/relay_worlds/lobby/v1", "gno.land")
	if path == "" {
		if published.answer == "" {
			return page + "The Signal Room puzzle is unavailable.\n"
		}
		return page + "Open this room with your run ID after accepting the invitation in the " +
			"[Lobby](" + lobbyBase + "). Add a colon and the run ID to this page's URL.\n"
	}

	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil || id <= 0 || strconv.FormatInt(id, 10) != path {
		return page + "Run does not exist.\n"
	}
	playerA, playerB, accepted, exists := lobby.GetRun(id)
	if !exists {
		return page + "Run does not exist.\n"
	}

	page += "## Run " + path + "\n\nPlayer A · " + playerA.String() +
		"\n\nPlayer B · " + playerB.String() + "\n\n" +
		"[Back to the Lobby run](" + lobbyBase + ":" + path + ")\n\n"
	if !accepted {
		return page + "**Awaiting acceptance.** Player B must accept the invitation in the Lobby.\n"
	}
	if published.answer == "" {
		return page + "The Signal Room puzzle is unavailable.\n"
	}

	page += "**Color sequence** · " + published.sequence + "\n\n**Color key** · " + published.legend + "\n\n"
	if IsComplete(id) {
		return page + "**Signal decoded.** Switch order · " + published.switchOrder + "\n"
	}
	return page + "Use the color key to read the code in order. Player A submits the answer.\n\n" +
		"[Enter the code](" + base + "$help&func=Solve&runID=" + path + ")\n"
}

package tokeninfo

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/sys/users"
)

const maxEditors = 10

// tokenExists and resolveName are variables only so tests can stand in for
// grc20reg and r/sys/users.
var (
	tokenExists = func(token string) bool { return grc20reg.Get(token) != nil }
	resolveName = func(name string) (address, bool) {
		data, isCurrent := users.ResolveName(name)
		if data == nil || !isCurrent {
			return "", false
		}
		return data.Addr(), true
	}
)

// authorize returns who is calling and with which role, or panics. A realm
// caller is trusted only as the token's own realm; a user caller (MsgCall or
// MsgRun) as the namespace owner or an editor.
func authorize(cur realm, token string) (address, string) {
	if !cur.IsCurrent() {
		panic("tokeninfo: invalid realm")
	}
	pkg, ns := mustToken(token)
	prev := cur.Previous()
	who := prev.Address()
	if !prev.IsUser() {
		if prev.PkgPath() == pkg {
			return who, RoleRealm
		}
		panic("tokeninfo: only " + pkg + " can write this profile from code")
	}
	if ownsNamespace(who, ns) {
		return who, RoleOwner
	}
	if IsEditor(token, who) {
		return who, RoleEditor
	}
	panic("tokeninfo: " + who.String() + " does not own " + pkg + " and is not an editor")
}

// mustToken checks that token is a valid token path listed in grc20reg, and
// returns its realm path and namespace.
func mustToken(token string) (pkg, ns string) {
	pkg, ns, ok := parseToken(token)
	if !ok {
		panic("tokeninfo: " + token + " is not a token path like gno.land/r/name/token.SYMBOL")
	}
	if !tokenExists(token) {
		panic("tokeninfo: " + token + " is not listed in grc20reg")
	}
	return pkg, ns
}

// ownsNamespace applies the same two rules the chain uses to let someone
// deploy under a namespace: it is their own address, or a name they hold now.
func ownsNamespace(who address, ns string) bool {
	if ns == "" || !who.IsValid() {
		return false
	}
	if who.String() == ns {
		return true
	}
	owner, ok := resolveName(ns)
	return ok && owner == who
}

// IsEditor reports whether addr was added as an editor of token.
func IsEditor(token string, addr address) bool {
	set := editors.Get(token)
	return set != nil && set.(*avl.Tree).Has(addr.String())
}

// CanEdit reports whether addr, signing a transaction itself, could write the
// profile of token right now. Apps use it to show or hide an edit button.
func CanEdit(token string, addr address) bool {
	_, ns, ok := parseToken(token)
	return ok && (ownsNamespace(addr, ns) || IsEditor(token, addr))
}

package tokeninfo

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strings"
)

// selfPath is this realm's gnoweb path, e.g. /r/dexvision/tokeninfo.
var selfPath string

// init runs once, inside the MsgAddPackage that deploys the realm. There, and
// only there, unsafe.PreviousRealm() is the deployer and unsafe.CurrentRealm()
// is this realm (interrealm spec v2, section 12.3). Nothing else in the realm
// uses chain/runtime/unsafe: every crossing function reads cur.Previous().
func init() {
	admin = unsafe.PreviousRealm().Address()
	selfPath = strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

package tokeninfo

import "gno.land/p/nt/avl/v0"

// Get returns a copy of the profile of token. ok is false when there is none
// or a moderator has hidden it.
func Get(token string) (p Profile, ok bool) {
	v := profiles.Get(token)
	if v == nil || hidden.Has(token) {
		return Profile{}, false
	}
	return *(v.(*Profile)), true
}

// Fields is Get for clients that read with vm/qeval, which prints one value
// per line. Everything is empty when there is no visible profile.
func Fields(token string) (description, website, logo, x, telegram, discord, github, updatedBy string, updatedAt int64, role string) {
	p, ok := Get(token)
	if !ok {
		return
	}
	return p.Description, p.Website, p.Logo, p.X, p.Telegram, p.Discord, p.GitHub, p.UpdatedBy.String(), p.UpdatedAt, p.Role
}

// HiddenReason returns why a moderator hid token, or "".
func HiddenReason(token string) string {
	if v := hidden.Get(token); v != nil {
		return v.(string)
	}
	return ""
}

// Editors returns the editors of token, in address order.
func Editors(token string) []address {
	var out []address
	if set := editors.Get(token); set != nil {
		set.(*avl.Tree).Iterate("", "", func(k string, _ any) bool {
			out = append(out, address(k))
			return false
		})
	}
	return out
}

// Count returns how many tokens have a profile, hidden ones included.
func Count() int { return profiles.Size() }

// List returns up to limit token paths with a profile, in path order,
// starting at offset. Hidden ones are included; check with Get.
func List(offset, limit int) []string {
	if limit > 100 {
		limit = 100
	}
	var out []string
	profiles.IterateByOffset(offset, limit, func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

package tokeninfo

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/fqname/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const pageSize = 50

// tokenName is a variable only so tests can stand in for grc20reg.
var tokenName = func(token string) string {
	if t := grc20reg.Get(token); t != nil {
		return t.GetName()
	}
	return ""
}

// Render serves the registry home at "" (with ?page=N) and one profile at
// its token path, e.g. :gno.land/r/gnoswap/gns.GNS.
func Render(path string) string {
	if path == "" || strings.HasPrefix(path, "?") {
		return renderHome(path)
	}
	return renderToken(path)
}

func renderHome(query string) string {
	page := 1
	if v := strings.TrimPrefix(query, "?page="); v != query {
		if n, err := strconv.Atoi(v); err == nil && n > 1 {
			page = n
		}
	}
	out := "# Token profiles\n\n" +
		"Official links for GRC20 tokens on gno.land, written on-chain by the people behind each token: " +
		"the owner of the namespace the token lives in, the token realm itself, or editors they add. " +
		"Apps read them with `Get` or `Fields`, so a project fills them in once and every explorer shows the same verified data.\n\n" +
		"**" + strconv.Itoa(Count()) + "** tokens have a profile.\n\n"
	list := List((page-1)*pageSize, pageSize)
	if len(list) == 0 {
		out += "_No profiles on this page._\n\n"
	} else {
		out += "| Token | Name | Updated at block |\n| --- | --- | --- |\n"
		for _, token := range list {
			_, symbol := fqname.Parse(token)
			updated := "hidden"
			if p, ok := Get(token); ok {
				updated = strconv.FormatInt(p.UpdatedAt, 10)
			}
			out += "| [" + sanitize.TableCell(symbol) + "](" + selfPath + ":" + token + ") | " +
				sanitize.TableCell(tokenName(token)) + " | " + updated + " |\n"
		}
		out += "\n"
	}
	if page > 1 {
		out += "[Previous page](" + selfPath + ":?page=" + strconv.Itoa(page-1) + ") "
	}
	if page*pageSize < Count() {
		out += "[Next page](" + selfPath + ":?page=" + strconv.Itoa(page+1) + ")"
	}
	out += "\n\n## Add your token\n\n" +
		"Sign from the address that owns the token's namespace (or from the token realm):\n\n" +
		"```\ngnokey maketx call -pkgpath " + runtime.ChainDomain() + selfPath + " -func SetProfile \\\n" +
		"  -args gno.land/r/<you>/<token>.<SYMBOL> -args \"<description>\" -args https://<website> \\\n" +
		"  -args https://<logo.png> -args <x handle> -args <telegram> -args https://discord.gg/<invite> -args <github> \\\n" +
		"  -gas-fee 1000000ugnot -gas-wanted 20000000 -broadcast -chainid <chain> -remote <rpc> <key>\n```\n\n" +
		"Or use the profile editor on any token page of [DexVision](https://dexvision.pro).\n"
	return out
}

func renderToken(token string) string {
	pkg, ns, ok := parseToken(token)
	if !ok {
		return "# Not a token path\n\nUse a path like `gno.land/r/gnoswap/gns.GNS`.\n"
	}
	_, symbol := fqname.Parse(token)
	head := "# " + sanitize.InlineText(symbol)
	if name := tokenName(token); name != "" {
		head += ": " + sanitize.InlineText(name)
	}
	out := head + "\n\n" + sanitize.InlineCode(token) + " · [source](" + strings.TrimPrefix(pkg, runtime.ChainDomain()) + "$source)\n\n"

	if reason := HiddenReason(token); reason != "" {
		return out + "> This profile was hidden by the moderator: " + sanitize.InlineText(reason) + "\n\n[All profiles](" + selfPath + ")\n"
	}
	p, found := Get(token)
	if !found {
		return out + "No profile yet. The owner of the `" + sanitize.InlineText(ns) + "` namespace can add one with `SetProfile`.\n\n[All profiles](" + selfPath + ")\n"
	}
	if logo := sanitize.ImageURL(p.Logo); logo != "" {
		out += "![" + sanitize.InlineText(symbol) + " logo](" + logo + ")\n\n"
	}
	if p.Description != "" {
		out += sanitize.InlineText(p.Description) + "\n\n"
	}
	out += link("Website", p.Website, p.Website)
	if p.X != "" {
		out += link("X", "@"+p.X, "https://x.com/"+p.X)
	}
	if p.Telegram != "" {
		out += link("Telegram", "@"+p.Telegram, "https://t.me/"+p.Telegram)
	}
	out += link("Discord", p.Discord, p.Discord)
	if p.GitHub != "" {
		out += link("GitHub", p.GitHub, "https://github.com/"+p.GitHub)
	}
	out += "\nUpdated at block " + strconv.FormatInt(p.UpdatedAt, 10) + " by " + sanitize.InlineCode(p.UpdatedBy.String()) + " (" + roleText(p.Role) + ").\n"
	if eds := Editors(token); len(eds) > 0 {
		out += "\nEditors:"
		for _, e := range eds {
			out += " " + sanitize.InlineCode(e.String())
		}
		out += "\n"
	}
	return out + "\n[All profiles](" + selfPath + ")\n"
}

func link(label, text, url string) string {
	safe := sanitize.URL(url)
	if text == "" || safe == "" {
		return ""
	}
	return "- " + label + ": [" + sanitize.InlineText(text) + "](" + safe + ")\n"
}

func roleText(role string) string {
	switch role {
	case RoleOwner:
		return "namespace owner"
	case RoleRealm:
		return "token realm"
	case RoleEditor:
		return "editor"
	}
	return role
}

// Package tokeninfo is an on-chain registry of token profiles: a description,
// a logo and official links for any GRC20 token listed in grc20reg.
//
// Only the people behind a token can write its profile:
//
//   - the owner of the namespace the token was deployed under, that is the
//     address in gno.land/r/g1.../ or the current owner of the registered
//     name in gno.land/r/<name>/ (see r/sys/users);
//   - the token's own realm, calling from its code;
//   - editors the owner (or the token realm) has added.
//
// Explorers, wallets and other realms read profiles with Get or Fields, so a
// project fills in its links once and every app shows the same verified data.
package tokeninfo

import (
	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Roles say why a caller may edit a profile.
const (
	RoleOwner  = "owner"  // owns the token's namespace
	RoleRealm  = "realm"  // the token's own realm
	RoleEditor = "editor" // added by the owner or the realm
)

// Profile is what a token publishes about itself. Every field is optional.
type Profile struct {
	Token       string // token path, e.g. gno.land/r/gnoswap/gns.GNS
	Description string
	Website     string // https URL
	Logo        string // https URL of an image
	X           string // handle, without @
	Telegram    string // handle, without @
	Discord     string // https://discord.gg/... invite
	GitHub      string // owner or owner/repo
	UpdatedBy   address
	UpdatedAt   int64  // block height
	Role        string // RoleOwner, RoleRealm or RoleEditor
}

var (
	profiles = avl.NewTree() // token path -> *Profile
	editors  = avl.NewTree() // token path -> *avl.Tree (address -> true)
	hidden   = avl.NewTree() // token path -> reason (string)

	// admin can only hide and unhide profiles; it can never write one. The
	// deployer (set in init) until it calls TransferAdmin.
	admin address
)

// SetProfile creates or replaces the whole profile of token. Empty fields are
// cleared. The caller must be the namespace owner, the token realm or an editor.
func SetProfile(cur realm, token, description, website, logo, x, telegram, discord, github string) {
	who, role := authorize(cur, token)
	p := &Profile{
		Token:       token,
		Description: mustDescription(description),
		Website:     mustURL("website", website),
		Logo:        mustURL("logo", logo),
		X:           mustHandle("x", x, 1, 15, false),
		Telegram:    mustHandle("telegram", telegram, 5, 32, false),
		Discord:     mustDiscord(discord),
		GitHub:      mustGitHub(github),
		UpdatedBy:   who,
		UpdatedAt:   runtime.ChainHeight(),
		Role:        role,
	}
	profiles.Set(token, p)
	chain.Emit("ProfileSet", "token", token, "by", who.String(), "role", role)
}

// ClearProfile deletes the profile of token. Editors stay.
func ClearProfile(cur realm, token string) {
	who, role := authorize(cur, token)
	if _, removed := profiles.Remove(token); !removed {
		panic("tokeninfo: " + token + " has no profile")
	}
	chain.Emit("ProfileCleared", "token", token, "by", who.String(), "role", role)
}

// AddEditor lets editor write the profile of token. Only the namespace owner
// or the token realm can add editors.
func AddEditor(cur realm, token string, editor address) {
	who, role := authorize(cur, token)
	if role == RoleEditor {
		panic("tokeninfo: editors cannot add editors")
	}
	if !editor.IsValid() {
		panic("tokeninfo: invalid editor address")
	}
	set := editors.Get(token)
	if set == nil {
		set = avl.NewTree()
		editors.Set(token, set)
	}
	if set.(*avl.Tree).Size() >= maxEditors {
		panic("tokeninfo: too many editors")
	}
	set.(*avl.Tree).Set(editor.String(), true)
	chain.Emit("EditorAdded", "token", token, "editor", editor.String(), "by", who.String())
}

// RemoveEditor revokes editor. The owner and the token realm can remove anyone;
// an editor can remove only itself.
func RemoveEditor(cur realm, token string, editor address) {
	who, role := authorize(cur, token)
	if role == RoleEditor && who != editor {
		panic("tokeninfo: editors can only remove themselves")
	}
	set := editors.Get(token)
	if set == nil {
		panic("tokeninfo: not an editor")
	}
	if _, removed := set.(*avl.Tree).Remove(editor.String()); !removed {
		panic("tokeninfo: not an editor")
	}
	if set.(*avl.Tree).Size() == 0 {
		editors.Remove(token)
	}
	chain.Emit("EditorRemoved", "token", token, "editor", editor.String(), "by", who.String())
}

// Hide takes a profile out of Get, Fields and Render, for abuse such as a
// phishing link. The reason is public. Admin only.
func Hide(cur realm, token, reason string) {
	assertAdmin(cur)
	if !profiles.Has(token) {
		panic("tokeninfo: " + token + " has no profile")
	}
	reason = mustText("reason", reason, maxReason)
	if reason == "" {
		panic("tokeninfo: a reason is required")
	}
	hidden.Set(token, reason)
	chain.Emit("ProfileHidden", "token", token, "reason", reason)
}

// Unhide shows a hidden profile again. Admin only.
func Unhide(cur realm, token string) {
	assertAdmin(cur)
	if _, removed := hidden.Remove(token); !removed {
		panic("tokeninfo: " + token + " is not hidden")
	}
	chain.Emit("ProfileUnhidden", "token", token)
}

// TransferAdmin hands moderation to another address. Admin only.
func TransferAdmin(cur realm, next address) {
	assertAdmin(cur)
	if !next.IsValid() {
		panic("tokeninfo: invalid admin address")
	}
	admin = next
	chain.Emit("AdminTransferred", "admin", next.String())
}

// Admin returns the moderation address.
func Admin() address { return admin }

func assertAdmin(cur realm) {
	if !cur.IsCurrent() {
		panic("tokeninfo: invalid realm")
	}
	if cur.Previous().Address() != admin {
		panic("tokeninfo: admin only")
	}
}

package tokeninfo

import (
	"chain/runtime"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/fqname/v0"
)

// parseToken splits a token path like gno.land/r/name/token.SYMBOL into its
// realm path and namespace. Segments are [a-z0-9_-]+ and the symbol is
// [A-Za-z0-9_-], 1 to 32 long, so a valid path is safe to put in a link.
func parseToken(token string) (pkg, ns string, ok bool) {
	if len(token) > maxToken {
		return "", "", false
	}
	pkg, symbol := fqname.Parse(token)
	if len(symbol) < 1 || len(symbol) > 32 || !charsIn(symbol, true) {
		return "", "", false
	}
	prefix := runtime.ChainDomain() + "/r/"
	if !strings.HasPrefix(pkg, prefix) {
		return "", "", false
	}
	segments := strings.Split(pkg[len(prefix):], "/")
	for _, s := range segments {
		if s == "" || !charsIn(s, false) {
			return "", "", false
		}
	}
	return pkg, segments[0], true
}

// charsIn reports whether s has only [a-z0-9_-], plus A-Z when upper is set.
func charsIn(s string, upper bool) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || c == '-' || upper && c >= 'A' && c <= 'Z'
		if !ok {
			return false
		}
	}
	return true
}

const (
	maxToken       = 200
	maxDescription = 280 // characters
	maxURL         = 200
	maxReason      = 200
)

// mustText rejects control characters and anything over max characters. The
// stored text is plain; Render escapes it, and apps must escape it too.
func mustText(field, s string, max int) string {
	s = strings.TrimSpace(s)
	if !utf8.ValidString(s) {
		panic("tokeninfo: " + field + " is not valid UTF-8")
	}
	if utf8.RuneCountInString(s) > max {
		panic("tokeninfo: " + field + " is longer than the limit")
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f || (r >= 0x80 && r < 0xa0) || r == 0x2028 || r == 0x2029 {
			panic("tokeninfo: " + field + " has a control character or line break")
		}
	}
	return s
}

func mustDescription(s string) string { return mustText("description", s, maxDescription) }

// mustURL accepts an https URL with a host and no characters that could break
// out of a link or an HTML attribute. Empty clears the field.
func mustURL(field, s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	if len(s) > maxURL {
		panic("tokeninfo: " + field + " URL is longer than the limit")
	}
	if !strings.HasPrefix(s, "https://") || len(s) == len("https://") || s[len("https://")] == '/' {
		panic("tokeninfo: " + field + " must be an https:// URL")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c <= ' ' || c >= 0x7f || strings.IndexByte("\"'<>\\`()[]{}|^", c) >= 0 {
			panic("tokeninfo: " + field + " URL has a character that is not allowed")
		}
	}
	return s
}

// mustDiscord accepts only Discord invite links.
func mustDiscord(s string) string {
	s = mustURL("discord", s)
	if s != "" && !strings.HasPrefix(s, "https://discord.gg/") && !strings.HasPrefix(s, "https://discord.com/invite/") {
		panic("tokeninfo: discord must be an invite link (https://discord.gg/...)")
	}
	return s
}

// mustHandle accepts letters, digits and underscores (plus hyphens when
// dash is set), between min and max long. A leading @ is dropped.
func mustHandle(field, s string, min, max int, dash bool) string {
	s = strings.TrimPrefix(strings.TrimSpace(s), "@")
	if s == "" {
		return ""
	}
	if len(s) < min || len(s) > max {
		panic("tokeninfo: " + field + " handle has the wrong length")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || dash && c == '-'
		if !ok {
			panic("tokeninfo: " + field + " handle has a character that is not allowed")
		}
	}
	return s
}

// mustGitHub accepts "owner" or "owner/repo".
func mustGitHub(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	owner, repo, hasRepo := strings.Cut(s, "/")
	owner = mustHandle("github", owner, 1, 39, true)
	if owner == "" || strings.HasPrefix(owner, "-") || strings.HasPrefix(s, "@") {
		panic("tokeninfo: github must be owner or owner/repo")
	}
	if !hasRepo {
		return owner
	}
	if repo == "" || len(repo) > 100 || repo == "." || repo == ".." {
		panic("tokeninfo: github repo name is not valid")
	}
	for i := 0; i < len(repo); i++ {
		c := repo[i]
		ok := c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-' || c == '.'
		if !ok {
			panic("tokeninfo: github repo name has a character that is not allowed")
		}
	}
	return owner + "/" + repo
}

package tokeninfo

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/r/nt/grc20reg/v0"
	"gno.land/r/sys/users"
)

const maxEditors = 10

// tokenExists and resolveName are variables only so tests can stand in for
// grc20reg and r/sys/users.
var (
	tokenExists = func(token string) bool { return grc20reg.Get(token) != nil }
	resolveName = func(name string) (address, bool) {
		data, isCurrent := users.ResolveName(name)
		if data == nil || !isCurrent {
			return "", false
		}
		return data.Addr(), true
	}
)

// authorize returns who is calling and with which role, or panics. A realm
// caller is trusted only as the token's own realm; a user caller (MsgCall or
// MsgRun) as the namespace owner or an editor.
func authorize(cur realm, token string) (address, string) {
	if !cur.IsCurrent() {
		panic("tokeninfo: invalid realm")
	}
	pkg, ns := mustToken(token)
	prev := cur.Previous()
	who := prev.Address()
	if !prev.IsUser() {
		if prev.PkgPath() == pkg {
			return who, RoleRealm
		}
		panic("tokeninfo: only " + pkg + " can write this profile from code")
	}
	if ownsNamespace(who, ns) {
		return who, RoleOwner
	}
	if IsEditor(token, who) {
		return who, RoleEditor
	}
	panic("tokeninfo: " + who.String() + " does not own " + pkg + " and is not an editor")
}

// mustToken checks that token is a valid token path listed in grc20reg, and
// returns its realm path and namespace.
func mustToken(token string) (pkg, ns string) {
	pkg, ns, ok := parseToken(token)
	if !ok {
		panic("tokeninfo: " + token + " is not a token path like gno.land/r/name/token.SYMBOL")
	}
	if !tokenExists(token) {
		panic("tokeninfo: " + token + " is not listed in grc20reg")
	}
	return pkg, ns
}

// ownsNamespace applies the same two rules the chain uses to let someone
// deploy under a namespace: it is their own address, or a name they hold now.
func ownsNamespace(who address, ns string) bool {
	if ns == "" || !who.IsValid() {
		return false
	}
	if who.String() == ns {
		return true
	}
	owner, ok := resolveName(ns)
	return ok && owner == who
}

// IsEditor reports whether addr was added as an editor of token.
func IsEditor(token string, addr address) bool {
	set := editors.Get(token)
	return set != nil && set.(*avl.Tree).Has(addr.String())
}

// CanEdit reports whether addr, signing a transaction itself, could write the
// profile of token right now. Apps use it to show or hide an edit button.
func CanEdit(token string, addr address) bool {
	_, ns, ok := parseToken(token)
	return ok && (ownsNamespace(addr, ns) || IsEditor(token, addr))
}

package tokeninfo

import (
	"chain/runtime"
	"strings"
)

// selfPath is this realm's gnoweb path, e.g. /r/<addr>/tokeninfo/v1.
var selfPath string

// init runs once, in the transaction that deploys the realm: the previous
// realm is the account that published it, which moderates until it calls
// TransferAdmin.
func init(cur realm) {
	admin = cur.Previous().Address()
	selfPath = strings.TrimPrefix(cur.PkgPath(), runtime.ChainDomain())
}

package tokeninfo

import "gno.land/p/nt/avl/v0"

// Get returns a copy of the profile of token. ok is false when there is none
// or a moderator has hidden it.
func Get(token string) (p Profile, ok bool) {
	v := profiles.Get(token)
	if v == nil || hidden.Has(token) {
		return Profile{}, false
	}
	return *(v.(*Profile)), true
}

// Fields is Get for clients that read with vm/qeval, which prints one value
// per line. Everything is empty when there is no visible profile.
func Fields(token string) (description, website, logo, x, telegram, discord, github, updatedBy string, updatedAt int64, role string) {
	p, ok := Get(token)
	if !ok {
		return
	}
	return p.Description, p.Website, p.Logo, p.X, p.Telegram, p.Discord, p.GitHub, p.UpdatedBy.String(), p.UpdatedAt, p.Role
}

// HiddenReason returns why a moderator hid token, or "".
func HiddenReason(token string) string {
	if v := hidden.Get(token); v != nil {
		return v.(string)
	}
	return ""
}

// Editors returns the editors of token, in address order.
func Editors(token string) []address {
	var out []address
	if set := editors.Get(token); set != nil {
		set.(*avl.Tree).Iterate("", "", func(k string, _ any) bool {
			out = append(out, address(k))
			return false
		})
	}
	return out
}

// Count returns how many tokens have a profile, hidden ones included.
func Count() int { return profiles.Size() }

// List returns up to limit token paths with a profile, in path order,
// starting at offset. Hidden ones are included; check with Get.
func List(offset, limit int) []string {
	if limit > 100 {
		limit = 100
	}
	var out []string
	profiles.IterateByOffset(offset, limit, func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

package tokeninfo

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/fqname/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const pageSize = 50

// tokenName is a variable only so tests can stand in for grc20reg.
var tokenName = func(token string) string {
	if t := grc20reg.Get(token); t != nil {
		return t.GetName()
	}
	return ""
}

// Render serves the registry home at "" (with ?page=N) and one profile at
// its token path, e.g. :gno.land/r/gnoswap/gns.GNS.
func Render(path string) string {
	if path == "" || strings.HasPrefix(path, "?") {
		return renderHome(path)
	}
	return renderToken(path)
}

func renderHome(query string) string {
	page := 1
	if v := strings.TrimPrefix(query, "?page="); v != query {
		if n, err := strconv.Atoi(v); err == nil && n > 1 {
			page = n
		}
	}
	out := "# Token profiles\n\n" +
		"Official links for GRC20 tokens on gno.land, written on-chain by the people behind each token: " +
		"the owner of the namespace the token lives in, the token realm itself, or editors they add. " +
		"Apps read them with `Get` or `Fields`, so a project fills them in once and every explorer shows the same verified data.\n\n" +
		"**" + strconv.Itoa(Count()) + "** tokens have a profile.\n\n"
	list := List((page-1)*pageSize, pageSize)
	if len(list) == 0 {
		out += "_No profiles on this page._\n\n"
	} else {
		out += "| Token | Name | Updated at block |\n| --- | --- | --- |\n"
		for _, token := range list {
			_, symbol := fqname.Parse(token)
			updated := "hidden"
			if p, ok := Get(token); ok {
				updated = strconv.FormatInt(p.UpdatedAt, 10)
			}
			out += "| [" + sanitize.TableCell(symbol) + "](" + selfPath + ":" + token + ") | " +
				sanitize.TableCell(tokenName(token)) + " | " + updated + " |\n"
		}
		out += "\n"
	}
	if page > 1 {
		out += "[Previous page](" + selfPath + ":?page=" + strconv.Itoa(page-1) + ") "
	}
	if page*pageSize < Count() {
		out += "[Next page](" + selfPath + ":?page=" + strconv.Itoa(page+1) + ")"
	}
	out += "\n\n## Add your token\n\n" +
		"Sign from the address that owns the token's namespace (or from the token realm):\n\n" +
		"```\ngnokey maketx call -pkgpath " + runtime.ChainDomain() + selfPath + " -func SetProfile \\\n" +
		"  -args gno.land/r/<you>/<token>.<SYMBOL> -args \"<description>\" -args https://<website> \\\n" +
		"  -args https://<logo.png> -args <x handle> -args <telegram> -args https://discord.gg/<invite> -args <github> \\\n" +
		"  -gas-fee 1000000ugnot -gas-wanted 20000000 -broadcast -chainid <chain> -remote <rpc> <key>\n```\n\n" +
		"Or use the profile editor on any token page of [DexVision](https://dexvision.pro).\n"
	return out
}

func renderToken(token string) string {
	pkg, ns, ok := parseToken(token)
	if !ok {
		return "# Not a token path\n\nUse a path like `gno.land/r/gnoswap/gns.GNS`.\n"
	}
	_, symbol := fqname.Parse(token)
	head := "# " + sanitize.InlineText(symbol)
	if name := tokenName(token); name != "" {
		head += ": " + sanitize.InlineText(name)
	}
	out := head + "\n\n" + sanitize.InlineCode(token) + " · [source](" + strings.TrimPrefix(pkg, runtime.ChainDomain()) + "$source)\n\n"

	if reason := HiddenReason(token); reason != "" {
		return out + "> This profile was hidden by the moderator: " + sanitize.InlineText(reason) + "\n\n[All profiles](" + selfPath + ")\n"
	}
	p, found := Get(token)
	if !found {
		return out + "No profile yet. The owner of the `" + sanitize.InlineText(ns) + "` namespace can add one with `SetProfile`.\n\n[All profiles](" + selfPath + ")\n"
	}
	if logo := sanitize.ImageURL(p.Logo); logo != "" {
		out += "![" + sanitize.InlineText(symbol) + " logo](" + logo + ")\n\n"
	}
	if p.Description != "" {
		out += sanitize.InlineText(p.Description) + "\n\n"
	}
	out += link("Website", p.Website, p.Website)
	if p.X != "" {
		out += link("X", "@"+p.X, "https://x.com/"+p.X)
	}
	if p.Telegram != "" {
		out += link("Telegram", "@"+p.Telegram, "https://t.me/"+p.Telegram)
	}
	out += link("Discord", p.Discord, p.Discord)
	if p.GitHub != "" {
		out += link("GitHub", p.GitHub, "https://github.com/"+p.GitHub)
	}
	out += "\nUpdated at block " + strconv.FormatInt(p.UpdatedAt, 10) + " by " + sanitize.InlineCode(p.UpdatedBy.String()) + " (" + roleText(p.Role) + ").\n"
	if eds := Editors(token); len(eds) > 0 {
		out += "\nEditors:"
		for _, e := range eds {
			out += " " + sanitize.InlineCode(e.String())
		}
		out += "\n"
	}
	return out + "\n[All profiles](" + selfPath + ")\n"
}

func link(label, text, url string) string {
	safe := sanitize.URL(url)
	if text == "" || safe == "" {
		return ""
	}
	return "- " + label + ": [" + sanitize.InlineText(text) + "](" + safe + ")\n"
}

func roleText(role string) string {
	switch role {
	case RoleOwner:
		return "namespace owner"
	case RoleRealm:
		return "token realm"
	case RoleEditor:
		return "editor"
	}
	return role
}

// Package tokeninfo is an on-chain registry of token profiles: a description,
// a logo and official links for any GRC20 token listed in grc20reg.
//
// Only the people behind a token can write its profile:
//
//   - the owner of the namespace the token was deployed under, that is the
//     address in gno.land/r/g1.../ or the current owner of the registered
//     name in gno.land/r/<name>/ (see r/sys/users);
//   - the token's own realm, calling from its code;
//   - editors the owner (or the token realm) has added.
//
// Explorers, wallets and other realms read profiles with Get or Fields, so a
// project fills in its links once and every app shows the same verified data.
package tokeninfo

import (
	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Roles say why a caller may edit a profile.
const (
	RoleOwner  = "owner"  // owns the token's namespace
	RoleRealm  = "realm"  // the token's own realm
	RoleEditor = "editor" // added by the owner or the realm
)

// Profile is what a token publishes about itself. Every field is optional.
type Profile struct {
	Token       string // token path, e.g. gno.land/r/gnoswap/gns.GNS
	Description string
	Website     string // https URL
	Logo        string // https URL of an image
	X           string // handle, without @
	Telegram    string // handle, without @
	Discord     string // https://discord.gg/... invite
	GitHub      string // owner or owner/repo
	UpdatedBy   address
	UpdatedAt   int64  // block height
	Role        string // RoleOwner, RoleRealm or RoleEditor
}

var (
	profiles = avl.NewTree() // token path -> *Profile
	editors  = avl.NewTree() // token path -> *avl.Tree (address -> true)
	hidden   = avl.NewTree() // token path -> reason (string)

	// admin can only hide and unhide profiles; it can never write one. The
	// deployer (set in init) until it calls TransferAdmin.
	admin address
)

// SetProfile creates or replaces the whole profile of token. Empty fields are
// cleared. The caller must be the namespace owner, the token realm or an editor.
func SetProfile(cur realm, token, description, website, logo, x, telegram, discord, github string) {
	who, role := authorize(cur, token)
	p := &Profile{
		Token:       token,
		Description: mustDescription(description),
		Website:     mustURL("website", website),
		Logo:        mustURL("logo", logo),
		X:           mustHandle("x", x, 1, 15, false),
		Telegram:    mustHandle("telegram", telegram, 5, 32, false),
		Discord:     mustDiscord(discord),
		GitHub:      mustGitHub(github),
		UpdatedBy:   who,
		UpdatedAt:   runtime.ChainHeight(),
		Role:        role,
	}
	profiles.Set(token, p)
	chain.Emit("ProfileSet", "token", token, "by", who.String(), "role", role)
}

// ClearProfile deletes the profile of token. Editors stay.
func ClearProfile(cur realm, token string) {
	who, role := authorize(cur, token)
	if _, removed := profiles.Remove(token); !removed {
		panic("tokeninfo: " + token + " has no profile")
	}
	chain.Emit("ProfileCleared", "token", token, "by", who.String(), "role", role)
}

// AddEditor lets editor write the profile of token. Only the namespace owner
// or the token realm can add editors.
func AddEditor(cur realm, token string, editor address) {
	who, role := authorize(cur, token)
	if role == RoleEditor {
		panic("tokeninfo: editors cannot add editors")
	}
	if !editor.IsValid() {
		panic("tokeninfo: invalid editor address")
	}
	set := editors.Get(token)
	if set == nil {
		set = avl.NewTree()
		editors.Set(token, set)
	}
	if set.(*avl.Tree).Size() >= maxEditors {
		panic("tokeninfo: too many editors")
	}
	set.(*avl.Tree).Set(editor.String(), true)
	chain.Emit("EditorAdded", "token", token, "editor", editor.String(), "by", who.String())
}

// RemoveEditor revokes editor. The owner and the token realm can remove anyone;
// an editor can remove only itself.
func RemoveEditor(cur realm, token string, editor address) {
	who, role := authorize(cur, token)
	if role == RoleEditor && who != editor {
		panic("tokeninfo: editors can only remove themselves")
	}
	set := editors.Get(token)
	if set == nil {
		panic("tokeninfo: not an editor")
	}
	if _, removed := set.(*avl.Tree).Remove(editor.String()); !removed {
		panic("tokeninfo: not an editor")
	}
	if set.(*avl.Tree).Size() == 0 {
		editors.Remove(token)
	}
	chain.Emit("EditorRemoved", "token", token, "editor", editor.String(), "by", who.String())
}

// Hide takes a profile out of Get, Fields and Render, for abuse such as a
// phishing link. The reason is public. Admin only.
func Hide(cur realm, token, reason string) {
	assertAdmin(cur)
	if !profiles.Has(token) {
		panic("tokeninfo: " + token + " has no profile")
	}
	reason = mustText("reason", reason, maxReason)
	if reason == "" {
		panic("tokeninfo: a reason is required")
	}
	hidden.Set(token, reason)
	chain.Emit("ProfileHidden", "token", token, "reason", reason)
}

// Unhide shows a hidden profile again. Admin only.
func Unhide(cur realm, token string) {
	assertAdmin(cur)
	if _, removed := hidden.Remove(token); !removed {
		panic("tokeninfo: " + token + " is not hidden")
	}
	chain.Emit("ProfileUnhidden", "token", token)
}

// TransferAdmin hands moderation to another address. Admin only.
func TransferAdmin(cur realm, next address) {
	assertAdmin(cur)
	if !next.IsValid() {
		panic("tokeninfo: invalid admin address")
	}
	admin = next
	chain.Emit("AdminTransferred", "admin", next.String())
}

// Admin returns the moderation address.
func Admin() address { return admin }

func assertAdmin(cur realm) {
	if !cur.IsCurrent() {
		panic("tokeninfo: invalid realm")
	}
	if cur.Previous().Address() != admin {
		panic("tokeninfo: admin only")
	}
}

package tokeninfo

import (
	"chain/runtime"
	"strings"
	"unicode/utf8"

	"gno.land/p/nt/fqname/v0"
)

// parseToken splits a token path like gno.land/r/name/token.SYMBOL into its
// realm path and namespace. Segments are [a-z0-9_-]+ and the symbol is
// [A-Za-z0-9_-], 1 to 32 long, so a valid path is safe to put in a link.
func parseToken(token string) (pkg, ns string, ok bool) {
	if len(token) > maxToken {
		return "", "", false
	}
	pkg, symbol := fqname.Parse(token)
	if len(symbol) < 1 || len(symbol) > 32 || !charsIn(symbol, true) {
		return "", "", false
	}
	prefix := runtime.ChainDomain() + "/r/"
	if !strings.HasPrefix(pkg, prefix) {
		return "", "", false
	}
	segments := strings.Split(pkg[len(prefix):], "/")
	for _, s := range segments {
		if s == "" || !charsIn(s, false) {
			return "", "", false
		}
	}
	return pkg, segments[0], true
}

// charsIn reports whether s has only [a-z0-9_-], plus A-Z when upper is set.
func charsIn(s string, upper bool) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '_' || c == '-' || upper && c >= 'A' && c <= 'Z'
		if !ok {
			return false
		}
	}
	return true
}

const (
	maxToken       = 200
	maxDescription = 280 // characters
	maxURL         = 200
	maxReason      = 200
)

// mustText rejects control characters and anything over max characters. The
// stored text is plain; Render escapes it, and apps must escape it too.
func mustText(field, s string, max int) string {
	s = strings.TrimSpace(s)
	if !utf8.ValidString(s) {
		panic("tokeninfo: " + field + " is not valid UTF-8")
	}
	if utf8.RuneCountInString(s) > max {
		panic("tokeninfo: " + field + " is longer than the limit")
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f || (r >= 0x80 && r < 0xa0) || r == 0x2028 || r == 0x2029 {
			panic("tokeninfo: " + field + " has a control character or line break")
		}
	}
	return s
}

func mustDescription(s string) string { return mustText("description", s, maxDescription) }

// mustURL accepts an https URL with a host and no characters that could break
// out of a link or an HTML attribute. Empty clears the field.
func mustURL(field, s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	if len(s) > maxURL {
		panic("tokeninfo: " + field + " URL is longer than the limit")
	}
	if !strings.HasPrefix(s, "https://") || len(s) == len("https://") || s[len("https://")] == '/' {
		panic("tokeninfo: " + field + " must be an https:// URL")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c <= ' ' || c >= 0x7f || strings.IndexByte("\"'<>\\`()[]{}|^", c) >= 0 {
			panic("tokeninfo: " + field + " URL has a character that is not allowed")
		}
	}
	return s
}

// mustDiscord accepts only Discord invite links.
func mustDiscord(s string) string {
	s = mustURL("discord", s)
	if s != "" && !strings.HasPrefix(s, "https://discord.gg/") && !strings.HasPrefix(s, "https://discord.com/invite/") {
		panic("tokeninfo: discord must be an invite link (https://discord.gg/...)")
	}
	return s
}

// mustHandle accepts letters, digits and underscores (plus hyphens when
// dash is set), between min and max long. A leading @ is dropped.
func mustHandle(field, s string, min, max int, dash bool) string {
	s = strings.TrimPrefix(strings.TrimSpace(s), "@")
	if s == "" {
		return ""
	}
	if len(s) < min || len(s) > max {
		panic("tokeninfo: " + field + " handle has the wrong length")
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || dash && c == '-'
		if !ok {
			panic("tokeninfo: " + field + " handle has a character that is not allowed")
		}
	}
	return s
}

// mustGitHub accepts "owner" or "owner/repo".
func mustGitHub(s string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return ""
	}
	owner, repo, hasRepo := strings.Cut(s, "/")
	owner = mustHandle("github", owner, 1, 39, true)
	if owner == "" || strings.HasPrefix(owner, "-") || strings.HasPrefix(s, "@") {
		panic("tokeninfo: github must be owner or owner/repo")
	}
	if !hasRepo {
		return owner
	}
	if repo == "" || len(repo) > 100 || repo == "." || repo == ".." {
		panic("tokeninfo: github repo name is not valid")
	}
	for i := 0; i < len(repo); i++ {
		c := repo[i]
		ok := c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-' || c == '.'
		if !ok {
			panic("tokeninfo: github repo name has a character that is not allowed")
		}
	}
	return owner + "/" + repo
}

// Package dxv is DexVision Demo (DXV), a testnet token with no value. It
// exists so anyone can try DexVision end to end on a chain where everything is
// free: claim some DXV, trade it on Gnoswap, and see its on-chain profile.
package dxv

import (
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	decimals    = 6
	unit        = 1_000_000         // 1 DXV
	supply      = 10_000_000 * unit // minted to the publisher
	faucetDrop  = 1_000 * unit      // per claim
	faucetEvery = int64(17_280)     // blocks, about a day at 5 s
	faucetCap   = 5_000_000 * unit  // total the faucet may ever mint
)

var (
	Token      *grc20.Token
	ledger     *grc20.PrivateLedger
	userTeller grc20.Teller
	lastClaim  = avl.NewTree() // address -> block height
	dropped    int64
)

func init(cur realm) {
	Token, ledger = grc20.NewToken("DexVision Demo", "DXV", decimals, 0, cur)
	userTeller = ledger.CallerTeller()
	// The publisher gets the supply to seed a Gnoswap pool. Unit tests run init
	// with no publisher, hence the check.
	if publisher := cur.Previous().Address(); publisher.IsValid() {
		checkErr(ledger.Mint(publisher, supply))
	}
	grc20reg.Register(cross(cur), Token, "")
}

func TotalSupply() int64                     { return userTeller.TotalSupply() }
func BalanceOf(owner address) int64          { return userTeller.BalanceOf(owner) }
func Allowance(owner, spender address) int64 { return userTeller.Allowance(owner, spender) }

func Transfer(cur realm, to address, amount int64) {
	checkErr(userTeller.Transfer(0, cur, to, amount))
}

func Approve(cur realm, spender address, amount int64) {
	checkErr(userTeller.Approve(0, cur, spender, amount))
}

func TransferFrom(cur realm, from, to address, amount int64) {
	checkErr(userTeller.TransferFrom(0, cur, from, to, amount))
}

// Faucet gives the caller 1,000 DXV, once a day per account.
func Faucet(cur realm) {
	prev := cur.Previous()
	if !prev.IsUser() {
		panic("dxv: claim from an account, not a contract")
	}
	who := prev.Address()
	now := runtime.ChainHeight()
	if v := lastClaim.Get(who.String()); v != nil && now-v.(int64) < faucetEvery {
		panic(ufmt.Sprintf("dxv: next claim at block %d", v.(int64)+faucetEvery))
	}
	if dropped+faucetDrop > faucetCap {
		panic("dxv: the faucet is empty")
	}
	lastClaim.Set(who.String(), now)
	dropped += faucetDrop
	checkErr(ledger.Mint(who, faucetDrop))
}

func Render(path string) string {
	if strings.HasPrefix(path, "balance/") {
		addr := address(strings.TrimPrefix(path, "balance/"))
		if !addr.IsValid() {
			return "Not an address."
		}
		return ufmt.Sprintf("%s has %s DXV.", addr.String(), formatDXV(userTeller.BalanceOf(addr)))
	}
	return "# DexVision Demo (DXV)\n\nA testnet token with no value, for trying [DexVision](https://dexvision.pro/?network=onyx) end to end.\n\n" +
		Token.RenderHome() + "\nClaim 1,000 DXV a day with `Faucet`.\n"
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

// formatDXV writes base units as DXV, e.g. 1500000 -> 1.500000.
func formatDXV(n int64) string {
	return ufmt.Sprintf("%d.%06d", n/unit, n%unit)
}

